function canViewPage(page){const user=state.currentUser;if(!user)return false;if(page==='action')return true;if(user.pages==='all'||['대표','전체 관리자'].includes(user.role)||['owner','admin'].includes(user.backendRole))return true;if(Array.isArray(user.permissions)&&user.permissions.length)return user.permissions.some(permission=>permission.page_key===page&&permission.can_view);if(Array.isArray(user.pages))return user.pages.includes(page);return page==='hub'}
function canApprovePage(page){const user=state.currentUser;if(!user)return false;if(['대표','전체 관리자'].includes(user.role)||['owner','admin'].includes(user.backendRole))return true;if(Array.isArray(user.permissions)&&user.permissions.length)return user.permissions.some(permission=>permission.page_key===page&&permission.can_approve);return ['팀 관리자','manager'].includes(user.role)&&Array.isArray(user.pages)&&user.pages.includes(page)}
function allowedNav(){return nav.map(([section,items])=>[section,items.filter(([id])=>canViewPage(id))]).filter(([,items])=>items.length)}
