function defaultPermissionPagesForUser(role,team=''){
 const common=['action','hub'];if(['owner','admin'].includes(role))return [];if(role==='viewer')return common;
 const rules=[[/판매|영업|리테일|store|sales/i,['targets','profitability','anomalies','sales','customers','returns','inventory']],[/상품|기획|md|merch/i,['sales','planning','design','market','designer']],[/디자인|design/i,['planning','design','market','designer']],[/생산|production|소싱/i,['design','production','inventory']],[/재고|물류|scm|logistics|warehouse/i,['sales','production','inventory']],[/마케팅|marketing|crm/i,['targets','profitability','customers','marketing','market']],[/고객|cs|cx|customer/i,['customers','returns']],[/데이터|ax|it|시스템|data/i,['anomalies','connections']]];
 const matched=rules.find(([pattern])=>pattern.test(String(team||'')))?.[1]||['anomalies','sales','inventory'];return [...new Set([...common,...matched])]
}
