function salesTabs(){return `<div class="sales-tabs">${[['overview','전체 판매'],['store','매장별'],['channel','채널별'],['product','제품별']].map(([id,label])=>`<button class="sales-tab ${state.salesView===id?'active':''}" data-sales-view="${id}">${label}</button>`).join('')}<button class="sales-tab ax-link" data-query="오늘 판매에서 가장 중요한 이상 신호를 보여줘">AX로 더 보기</button></div>`}
