function regionalSalesMap(){return `<div class="regional-map" aria-label="동아시아 지역별 매출 지도"><svg viewBox="0 0 560 280" role="img"><defs><linearGradient id="sea" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f5f8f5"/><stop offset="1" stop-color="#edf3ef"/></linearGradient></defs><rect width="560" height="280" rx="16" fill="url(#sea)"/><path class="map-land china" d="M35 58 L108 30 190 42 250 74 238 116 185 138 152 186 86 172 44 126Z"/><path class="map-land korea" d="M275 66 L296 78 304 116 290 150 276 136 281 104 268 86Z"/><path class="map-land japan" d="M354 72 L374 88 388 118 410 140 402 164 380 150 367 122 346 102Z"/><path class="map-land japan" d="M418 174 L438 183 448 202 433 211 414 194Z"/><circle class="map-pulse level-4" cx="288" cy="103" r="23"/><circle class="map-pulse level-2" cx="286" cy="139" r="14"/><circle class="map-pulse level-2" cx="216" cy="128" r="15"/><circle class="map-pulse level-1" cx="397" cy="137" r="11"/><g class="map-label"><text x="317" y="96">서울</text><text x="317" y="111">₩162.3M · 66.8%</text><text x="306" y="164">부산 ₩31.6M</text><text x="128" y="119">상하이 ₩35.7M</text><text x="416" y="129">도쿄 ₩13.5M</text></g></svg><div class="map-legend"><span><i class="l4"></i>₩100M+</span><span><i class="l2"></i>₩20–100M</span><span><i class="l1"></i>₩20M 미만</span></div></div>`}
function storeView(){return `${kpi([['오프라인 매출','₩243.1M','전체의 50.4%'],['판매 매장','18개','3개 국가'],['목표 달성 매장','11개','61.1%'],['평균 객단가','₩168.2K','+5.8%']])}<div class="grid split store-region-grid"><div class="card panel"><h2>매장 매출 구성비</h2>${bars(storeSales.map(r=>[r[0],`${r[2]} · ${r[3]}`,parseFloat(r[3])*6]))}</div><div class="card panel region-panel"><div class="panel-title"><h2>지역별 매출 지도</h2><span class="subtle">매출 규모별 색상 농도</span></div>${regionalSalesMap()}</div></div><div class="card panel"><h2>매장별 상세 판매</h2><table class="table"><thead><tr><th>매장</th><th>지역</th><th>순매출 · 구성비</th><th>판매수량</th><th>전년 대비</th><th>목표 달성률</th></tr></thead><tbody>${storeSales.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td><strong>${r[2]}</strong> <span class="percent-chip">${r[3]}</span></td><td>${r[4]} pcs</td><td class="delta ${r[5].startsWith('-')?'down':''}">${r[5]}</td><td>${r[6]}</td></tr>`).join('')}</tbody></table></div>`}
function channelView(){return `${kpi([['온라인 매출','₩364.2M','전체의 75.5%'],['연동 채널','6개','실시간 5개'],['온라인 전환율','4.1%','+0.5%p'],['반품률','8.4%','-1.2%p']])}<div class="grid split"><div class="card panel"><h2>채널 매출 구성비</h2>${bars(channelSales.map(r=>[r[0],`${r[2]} · ${r[3]}`,parseFloat(r[3])*3.5]))}</div><div class="card panel"><h2>채널별 성장률</h2>${bars(channelSales.map(r=>[r[0],r[5],Math.max(14,Math.abs(parseFloat(r[5]))*4),r[5].startsWith('-')?'warning':'']))}</div></div><div class="card panel"><h2>채널별 상세 판매</h2><table class="table"><thead><tr><th>채널</th><th>유형</th><th>순매출 · 구성비</th><th>판매수량</th><th>전년 대비</th><th>전환율</th></tr></thead><tbody>${channelSales.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td><strong>${r[2]}</strong> <span class="percent-chip">${r[3]}</span></td><td>${r[4]} pcs</td><td class="delta ${r[5].startsWith('-')?'down':''}">${r[5]}</td><td>${r[6]}</td></tr>`).join('')}</tbody></table></div>`}
function productView(){return `${kpi([['판매 제품','64 styles','16 categories'],['Top 4 매출','₩96.5M','전체의 20.0%'],['평균 판매율','71.8%','+6.1%p'],['성장 제품','42개','65.6%']])}<div class="card panel"><div class="panel-title"><h2>제품별 판매 상세</h2><span class="subtle">최근 7일 일별 판매 포함</span></div><table class="table trend-table"><thead><tr><th>제품</th><th>오늘 판매 · 구성비</th><th>매출 · 구성비</th><th>판매율</th><th>최근 7일 판매량 · 일별 눈금</th><th>전년 대비</th></tr></thead><tbody>${products.map((p,i)=>`<tr><td><div class="product-cell">${thumb(p.image,p.name)}<div><strong>${p.name}</strong><br><span class="subtle">${p.id} · ${p.designer}</span></div></div></td><td><strong>${[286,214,178,154][i]} pcs</strong> <span class="percent-chip">${[34.4,25.7,21.4,18.5][i]}%</span></td><td>₩${[36.8,25.2,18.4,16.1][i]}M <span class="percent-chip">${[38.1,26.1,19.1,16.7][i]}%</span></td><td>${p.sell}%</td><td>${dailyTrend(dailySeries[i])}</td><td class="delta ${p.delta.startsWith('-')?'down':''}">${p.delta}</td></tr>`).join('')}</tbody></table></div>`}
function dataModeLabel(mode){return mode==='stale'?['연결 지연','stale']:mode==='connected'?['연결 데이터','connected']:['샘플 데이터','sample']}
function dbOverviewBlock(){const d=state.dbOverview;if(!d)return '';const money=v=>`₩${(Number(v||0)/1000000).toLocaleString(undefined,{maximumFractionDigits:1})}M`,summary=d.summary||{},view=state.salesView,rows=(view==='store'?d.locations:view==='product'?d.products:view==='overview'?d.daily:d.channels)||[],metric=view==='product'?'quantity':'net_sales',total=rows.reduce((sum,row)=>sum+Number(row[metric]||0),0),max=Math.max(...rows.map(r=>Number(r[metric]||0)),1),[modeLabel,modeClass]=dataModeLabel(d.dataMode),freshAt=d.lastSuccessfulSyncAt||d.generatedAt,sourceNames=(d.sources||[]).map(source=>source.name).slice(0,3).join(' · ')||'판매 데이터 소스';if(!d.hasData)return `<section class="db-overview"><div class="data-provenance ${modeClass}"><strong>${modeLabel}</strong><span>마지막 정상 동기화 ${freshAt?new Date(freshAt).toLocaleString('ko-KR'):'없음'}</span></div><div class="card panel operational-empty"><strong>연결된 판매 데이터가 아직 없습니다.</strong><p>데이터 연결에서 판매 CSV/XLSX를 미리보기한 뒤 적재하면 이 화면의 지표가 실제 값으로 바뀝니다.</p><button class="btn primary" data-page="connections">판매 파일 연결하기</button></div></section>`;return `<section class="db-overview"><div class="data-provenance ${modeClass}"><strong>${modeLabel}</strong><span>${escapeHtml(sourceNames)} · 마지막 정상 동기화 ${new Date(freshAt).toLocaleString('ko-KR')}</span>${d.dataMode==='stale'?'<em>마지막 정상 데이터를 유지해 표시 중</em>':''}</div>${kpi([['최근 14일 순매출',money(summary.netSales),'연결 데이터 집계'],['판매수량',`${Number(summary.quantity||0).toLocaleString()} pcs`,'연결 데이터 집계'],['주문수',`${Number(summary.orders||0).toLocaleString()}건`,'중복 제거 주문'],['평균 주문금액',summary.orders?money(Number(summary.netSales)/Number(summary.orders)):'—','순매출 ÷ 주문수']])}${salesTabs()}<div class="card panel db-live-panel"><div class="panel-title"><div><h2>${view==='overview'?'일별 판매 추이':view==='store'?'매장별 판매':view==='product'?'제품별 판매':'채널별 판매'}</h2><span class="subtle">최근 14일 · 회사/계정 권한 범위 · 구성비 포함</span></div><button class="btn" data-page="connections">데이터 출처</button></div><div class="connected-sales-list">${rows.slice(0,16).map((r,index)=>{const value=Number(r[metric]||0),share=total?value/total*100:0,label=view==='overview'?new Date(r.label).toLocaleDateString('ko-KR',{month:'numeric',day:'numeric'}):r.label;return `<div class="connected-sales-row"><span class="connected-rank">${index+1}</span><div><strong>${escapeHtml(label)}</strong><small>${Number(r.quantity||0).toLocaleString()} pcs · ${Number(r.orders||0).toLocaleString()} orders</small></div><i><em style="--w:${Math.max(3,Math.round(value/max*100))}%"></em></i><b>${metric==='net_sales'?money(value):`${value.toLocaleString()} pcs`}<small>${share.toFixed(1)}%</small></b></div>`}).join('')}</div></div></section>`}
function hub(){if(state.backendMode==='connected'){if(state.dbOverviewLoading&&!state.dbOverview)return `<div class="card panel operational-loading">연결된 판매 데이터를 집계하고 있습니다.</div>`;return dbOverviewBlock()}const body=state.salesView==='store'?storeView():state.salesView==='channel'?channelView():state.salesView==='product'?productView():overviewSales();const headline=state.salesView==='overview'?kpi([['오늘 순매출','₩482.6M','샘플 · +11.8%'],['판매수량','3,842 pcs','샘플 · +8.2%'],['주문수','3,116건','샘플 · +7.4%'],['객단가','₩154.9K','샘플 · +4.1%']]):'';return `<div class="data-provenance sample"><strong>샘플 데이터</strong><span>데모용으로 생성된 값이며 고객 데이터와 혼합되지 않습니다.</span></div>${headline}${salesTabs()}${state.salesView==='overview'?phaseOneSummary()+customerHubSummary()+phaseThreeSummary():''}${body}`}
