function workflowTodayQueue(page){const queue=workflowActionQueues[page];if(!queue)return '';const p0=queue.items.filter(item=>item.priority==='P0').length;return `<section class="card workflow-today-queue"><header><div><small>TEAM DECIDE TODAY</small><h2>${queue.team} · 오늘 실행할 일</h2><p>현재 페이지의 판매·외부시장·재고·일정 신호를 실행 가능한 업무로 정리했습니다.</p></div><div class="workflow-queue-summary"><span><b>${queue.items.length}</b>개 할 일</span><span><b>${p0}</b>개 긴급</span><span><b>${queue.impact}</b></span></div></header><div class="workflow-today-grid">${queue.items.map(item=>`<article class="${item.priority==='P0'?'urgent':''}"><div class="workflow-task-meta">${priorityLabel(item.priority)}${tag(item.status,item.priority==='P0'?'warning':'')}</div><h3>${item.title}</h3><p>${item.basis}</p><dl><div><dt>담당</dt><dd>${item.owner}</dd></div><div><dt>마감</dt><dd>${item.due}</dd></div><div><dt>예상 효과</dt><dd>${item.impact}</dd></div></dl><footer><small>${item.source}</small><button data-query="${axEscape(item.title)}의 근거와 오늘 실행 순서를 알려줘">VIIM AX로 근거 보기</button></footer></article>`).join('')}</div><div class="workflow-queue-foot"><span>완료·지연 상태는 PLM·ERP·WMS·캠페인 데이터와 연결해 갱신합니다.</span><button data-page="action">전사 오늘의 액션 보기 →</button></div></section>`}
function currentTodayActions(){if(state.backendMode==='connected'&&state.todayActionsData)return state.todayActionsData.actions||[];return todayActions.map((action,index)=>({...action,key:`demo:${index}`,decision_status:state.todayActionStatuses[index]||'proposed',detail:todayActionDetails[index]}))}
function todayDetail(action,index){return action.detail||{owner:action.owner,due:action.due,recommendation:action.recommendation,approveLabel:action.approve_label,adjustLabel:action.adjust_label,evidence:action.evidence||[],effectTitle:action.effect_title,effectLines:action.effect_lines||[],riskTitle:action.risk_title,riskLines:action.risk_lines||[],constraints:action.constraints||[]}}
function todaySummary(){const actions=currentTodayActions(),server=state.backendMode==='connected'?state.todayActionsData?.summary:null,approved=server?.approved??actions.filter(action=>['approved','executed'].includes(action.decision_status)).length,pending=server?.pending??actions.length-approved,p0=server?.p0??actions.filter(action=>action.priority==='P0'&&!['approved','executed'].includes(action.decision_status)).length,due=server?.dueToday??3,impact=server?`₩${Math.round(Number(server.impactAmount||0)/1000000).toLocaleString()}M`:'₩73.9M';return `<section class="today-situation card"><h2>오늘 ${due}건의 마감 안건 중, 우선순위 ${p0}건을 먼저 결정하면 ${impact}의 기회를 보호할 수 있습니다.</h2><div class="today-summary-grid"><div><span>지금 결정</span><strong>${p0}건</strong><small>P0 우선순위</small></div><div><span>보호 가능 금액</span><strong class="accent">${impact}</strong><small>미결정 안건의 매출·비용 영향</small></div><div><span>오늘 마감</span><strong>${due}건</strong><small>결정 기한 기준</small></div><div><span>실행 중</span><strong>${approved}건</strong><small>승인 후 실제 업무 큐 연결</small></div></div></section>`}
function todayExecutionPanel(action,index){const detail=todayDetail(action,index),status=action.decision_status||'proposed',approved=['approved','executed'].includes(status);const steps=[['1','결정 승인',approved?'승인 완료':detail.due||'오늘 마감',approved?'완료':'대기'],['2','담당팀 실행 전환',detail.owner||'담당팀','예정'],['3','운영 데이터 확인','ERP · WMS · 채널 데이터','예정'],['4','성과 반영','대시보드 자동 갱신','예정']];return `<aside class="today-execution-panel card"><header><h2>결정 이후 흐름</h2><p>승인 후 실행까지 자동으로 이어집니다.</p></header><ol>${steps.map(([number,title,meta,stepStatus])=>`<li class="${stepStatus==='완료'?'done':stepStatus==='대기'?'waiting':''}"><b>${number}</b><div><strong>${escapeHtml(title)}</strong><small>${escapeHtml(meta)}</small></div><em>${stepStatus}</em></li>`).join('')}</ol><div class="today-automation-note"><strong>자동 실행 준비됨</strong><span>승인 시 실행 태스크와 담당팀 알림이 생성됩니다.</span></div></aside>`}
function todayDecisionCard(index){const actions=currentTodayActions(),action=actions[index],detail=todayDetail(action,index),status=action.decision_status||'proposed',approved=['approved','executed'].includes(status),busy=state.todayActionBusy===action.key;if(!action)return '';return `<div class="today-focus-layout"><section class="card today-decision-card" aria-live="polite"><header class="today-decision-header"><div class="today-action-identity"><span class="today-action-mark">${escapeHtml(String(action.title||'AX').replace(/[^A-Za-z0-9가-힣]/g,'').slice(0,3).toUpperCase()||'AX')}</span><div><div class="today-meta-row">${priorityLabel(action.priority)}${tag(action.type,action.priority==='P0'?'danger':action.priority==='P1'?'warning':'')}<span>${escapeHtml(action.source||'운영 데이터')}</span>${status!=='proposed'?workflowStatus(status):''}</div><h2>${escapeHtml(action.title)}</h2><p>담당 ${escapeHtml(detail.owner||'담당팀')} · 결정 기한 ${escapeHtml(detail.due||'오늘')} · 승인 전 자동 실행 없음</p></div></div><div class="today-confidence"><span>추천 신뢰도</span><strong>${escapeHtml(action.confidence||'—')}</strong></div></header><div class="today-evidence-strip"><div class="today-evidence-title"><span>판단 공식</span><strong>왜 지금 결정해야 하나</strong></div>${detail.evidence.map(([value,note])=>`<div class="today-evidence-item"><strong>${escapeHtml(value)}</strong><span>${escapeHtml(note)}</span></div>`).join('')}</div><div class="today-outcome-grid"><article class="today-outcome positive"><header><strong>승인하면</strong>${tag('권장')}</header><h3>${escapeHtml(detail.effectTitle)}</h3>${detail.effectLines.map(line=>`<p>${escapeHtml(line)}</p>`).join('')}</article><article class="today-outcome negative"><header><strong>미루면</strong>${tag('위험','danger')}</header><h3>${escapeHtml(detail.riskTitle)}</h3>${detail.riskLines.map(line=>`<p>${escapeHtml(line)}</p>`).join('')}</article></div><details class="today-constraints"><summary><span>결정 전 확인</span><strong>주요 제약 ${detail.constraints.length}가지 보기</strong></summary>${detail.constraints.map((constraint,i)=>`<p><b>0${i+1}</b>${escapeHtml(constraint)}</p>`).join('')}</details><footer class="today-decision-footer"><div><span>VIIM AX 권장 결정안</span><strong>${escapeHtml(detail.recommendation)}</strong></div><button class="btn" data-query="${axEscape(action.title)}의 근거 데이터와 가정을 보여줘">판단 근거 보기</button><button class="btn" data-today-adjust="${axEscape(action.key)}" data-action-title="${axEscape(action.title)}" ${busy||approved?'disabled':''}>${escapeHtml(detail.adjustLabel)}</button><button class="btn today-hold" data-today-hold="${axEscape(action.key)}" ${busy||approved?'disabled':''}>${status==='held'?'보류됨':'보류'}</button><button class="btn primary today-approve" data-today-approve="${axEscape(action.key)}" ${busy||approved?'disabled':''}>${busy?'처리 중…':approved?'승인 완료':escapeHtml(detail.approveLabel)}</button></footer></section>${todayExecutionPanel(action,index)}</div>`}
function todayQueue(selected){const actions=currentTodayActions(),queue=actions.map((action,index)=>({action,index,detail:todayDetail(action,index)})).filter(item=>item.index!==selected&&!['approved','executed'].includes(item.action.decision_status)).slice(0,3);return `<section class="card today-next-queue"><header><h2>다음 검토 안건 · ${queue.length}건</h2><button class="today-all-button" id="todayAllActions">전체 안건 ${actions.length}건 보기 <span aria-hidden="true">›</span></button></header><div class="today-queue-list">${queue.map(({action,index,detail})=>`<button class="today-queue-row" data-today-select="${index}" data-today-key="${axEscape(action.key)}" aria-label="${axEscape(action.title)} 상세 검토"><span>${priorityLabel(action.priority,true)}</span><strong>${escapeHtml(action.title)}</strong><em>${escapeHtml(detail.effectTitle)}</em><small>${escapeHtml(detail.owner)}</small><b>${escapeHtml(detail.due)}</b><i>상세 보기 <span aria-hidden="true">›</span></i></button>`).join('')}</div></section>`}
function todayAllActionsView(){const actions=currentTodayActions(),approved=actions.filter(action=>['approved','executed'].includes(action.decision_status)).length,due=state.todayActionsData?.summary?.dueToday??3;return `${todaySummary()}<section class="card today-all-actions"><header><div><span>DECIDE TODAY · DECISION QUEUE</span><h2>전체 안건</h2><p>우선순위, 담당 조직과 결정 기한을 확인하고 안건을 선택하세요.</p></div><button class="btn" id="todayActionBack">주요 안건으로 돌아가기</button></header><div class="today-all-summary"><span><b>${actions.length-approved}</b> 검토 필요</span><span><b>${approved}</b> 승인 완료</span><span><b>${due}</b> 오늘 마감</span></div><div class="today-all-list" role="list">${actions.map((action,index)=>{const detail=todayDetail(action,index),status=action.decision_status;return `<button role="listitem" data-today-select="${index}" data-today-key="${axEscape(action.key)}"><span>${priorityLabel(action.priority,true)}</span><div><strong>${escapeHtml(action.title)}</strong><small>${escapeHtml(action.scope)} · ${escapeHtml(action.type)}</small></div><em>${escapeHtml(detail.effectTitle)}</em><small>${escapeHtml(detail.owner)}</small><b>${escapeHtml(detail.due)}</b><i class="${['approved','executed'].includes(status)?'done':''}">${status==='approved'?'승인 완료':status==='held'?'보류됨':status==='adjustment_requested'?'조정 요청':'상세 검토'} <span aria-hidden="true">›</span></i></button>`}).join('')}</div></section>`}
function todaysAction(){if(state.backendMode==='connected'&&state.todayActionsLoading&&!state.todayActionsData)return '<div class="card panel operational-loading">판매·재고·예측·생산 신호에서 오늘의 안건을 만들고 있습니다.</div>';if(state.backendMode==='connected'&&state.todayActionsError&&!state.todayActionsData)return `<div class="data-provenance stale"><strong>오늘의 안건 조회 실패</strong><span>${escapeHtml(state.todayActionsError)}</span><button class="btn" id="refreshTodayActions">다시 시도</button></div>`;const actions=currentTodayActions();if(!actions.length)return `<div class="data-provenance connected"><strong>OPERATIONAL DECISION ENGINE</strong><span>현재 권한 범위의 운영 신호를 확인했습니다.</span><button class="btn" id="refreshTodayActions">새로고침</button></div><div class="card panel operational-empty"><strong>지금 결정이 필요한 안건이 없습니다.</strong><p>수요예측 또는 할인 최적화를 갱신하면 새로운 안건이 생성됩니다.</p></div>`;let selected=state.todaySelectedKey?actions.findIndex(action=>action.key===state.todaySelectedKey):-1;if(selected<0)selected=Math.min(Math.max(Number(state.todaySelected)||0,0),actions.length-1);state.todaySelected=selected;state.todaySelectedKey=actions[selected]?.key||null;const provenance=state.backendMode==='connected'?`<div class="data-provenance connected"><strong>OPERATIONAL DECISION ENGINE</strong><span>WMS · 수요예측 · 할인 최적화 · 생산 실행 데이터를 결합했습니다.</span><button class="btn" id="refreshTodayActions" ${state.todayActionsLoading?'disabled':''}>${state.todayActionsLoading?'갱신 중…':'안건 새로고침'}</button></div>`:'<div class="data-provenance sample"><strong>샘플 의사결정</strong><span>백엔드 연결 시 실제 운영 신호로 자동 교체됩니다.</span></div>';return `${provenance}${state.todayAllActions?todayAllActionsView():`${todaySummary()}${todayDecisionCard(selected)}${todayQueue(selected)}`}`}
const lifecycleTrend={day:{unit:'일 단위 · pcs',labels:['7/30','7/31','8/1','8/2','8/3','8/4','8/5'],actual:[184,211,228,246,274,302,318],ly:[151,172,184,202,218,236,251],forecast:[190,218,240,266,292,319,342]},week:{unit:'주 단위 · 누적 pcs',labels:['W1','W2','W3','W4','W5','W6','W7','W8'],actual:[302,686,1044,1312,1530,1702,1842,1984],ly:[264,548,806,1012,1188,1316,1420,1512],forecast:[318,724,1106,1438,1712,1940,2188,2460]}};
function trendPoints(values,max){return values.map((v,i)=>`${30+i*(650/(values.length-1))},${220-v/max*185}`).join(' ')}
function lifecycleTrendChart(){const d=lifecycleTrend[state.lifecyclePeriod],max=Math.ceil(Math.max(...d.forecast)/500)*500;return `<div class="period-tabs"><button class="${state.lifecyclePeriod==='day'?'active':''}" data-lifecycle-period="day">일 단위</button><button class="${state.lifecyclePeriod==='week'?'active':''}" data-lifecycle-period="week">주 단위</button><span>${d.unit}</span></div><div class="lifecycle-chart"><div class="y-ticks">${[max,Math.round(max*.75),Math.round(max*.5),Math.round(max*.25),0].map(v=>`<span>${v.toLocaleString()}</span>`).join('')}</div><div class="lifecycle-svg"><svg viewBox="0 0 710 245" preserveAspectRatio="none"><g class="grid-lines">${[35,81,127,173,220].map(y=>`<line x1="30" y1="${y}" x2="680" y2="${y}"/>`).join('')}</g><polyline class="ly" points="${trendPoints(d.ly,max)}"/><polyline class="forecast" points="${trendPoints(d.forecast,max)}"/><polyline class="actual" points="${trendPoints(d.actual,max)}"/>${d.actual.map((v,i)=>`<circle cx="${30+i*(650/(d.actual.length-1))}" cy="${220-v/max*185}" r="3"/>`).join('')}</svg><div class="x-ticks">${d.labels.map(x=>`<span>${x}</span>`).join('')}</div></div></div>`}
function sales(){return `${kpi([['오늘 판매속도','63 pcs/day','7일 평균 +18%'],['최근 7일 판매','392 pcs','전주 대비 +14.2%'],['초도 판매율','78.0%','1,842 / 2,360'],['예상 품절','8일','8월 14일']])}<div class="scope-note"><div><strong>이 페이지는 제품 수요 판단용입니다.</strong><span>일·주 판매속도, 초도 소진과 제품 생애주기를 봅니다. 전사 월 목표와 마감 예상은 별도 페이지에서 관리합니다.</span></div><button data-page="targets">전사 목표·마감예측 →</button></div><div class="grid split product-lifecycle-top"><div class="card panel lifecycle-trend-panel"><div class="panel-title"><div><h2>ARC-07 판매속도 · Actual vs LY vs Forecast</h2><span class="subtle">눈금과 단위를 전환해 단기 속도와 주간 누적을 비교합니다</span></div><div class="legend"><span><i style="background:#6b7b72"></i>전년</span><span><i style="background:#173d2b"></i>현재</span><span><i style="background:#b7ed4d"></i>예상</span></div></div>${lifecycleTrendChart()}</div><div class="card panel"><h2>선택 제품</h2><div class="product-focus">${photo('ARC-07 Utility Jacket',products[0].image)}<div class="focus-meta"><h3>ARC-07</h3><p>Utility Jacket · 성장 단계</p><strong>현재 1,842 pcs</strong><strong>초도 잔여 518 pcs</strong>${tag('8일 내 품절')}</div></div><div class="product-signal"><span>판매속도</span><strong>63 pcs/day</strong><span>재생산 제안</span><strong>840 pcs</strong></div></div></div><div class="card panel" style="min-height:320px"><div class="panel-title"><h2>제품별 판매속도 비교</h2><span class="subtle">최근 7일은 일별 눈금, 예상은 제품 수요 범위</span></div><table class="table trend-table"><thead><tr><th>제품</th><th>누적 판매</th><th>초도 판매율</th><th>예상 소진</th><th>최근 7일 판매량 · 일별 눈금</th><th>단계</th><th>Action</th></tr></thead><tbody>${products.map((p,i)=>`<tr><td><div class="product-cell">${thumb(p.image,p.id+' '+p.name)}<div><strong>${p.id}</strong><br><span class="subtle">${p.name}</span></div></div></td><td>${p.current.toLocaleString()} pcs</td><td>${p.sell}%</td><td>${[8,12,27,31][i]}일</td><td>${dailyTrend(dailySeries[i])}</td><td>${tag(['성장','성숙','둔화','유지'][i],i===2?'warning':'')}</td><td>${tag(i===0?'재생산':i===2?'콘텐츠 점검':'관찰',i===2?'warning':'')}</td></tr>`).join('')}</tbody></table></div>`}
