function lifecycleBlock(){return `<div class="card panel phase-card"><div class="panel-title"><div><h2>제품별 생애주기 판정</h2><span class="subtle">판매속도와 초도 소진율로 운영 단계를 매일 갱신합니다</span></div>${tag('DAILY UPDATED')}</div><div class="lifecycle-ribbon">${[['출시','8 styles'],['성장','14 styles'],['성숙','22 styles'],['둔화','12 styles'],['정리','8 styles']].map((x,i)=>`<div class="life-stage s${i}"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><table class="table lifecycle-table"><thead><tr><th>제품</th><th>출시일</th><th>경과</th><th>초도수량</th><th>누적판매</th><th>판매율</th><th>일 판매속도</th><th>예상 소진</th><th>단계</th></tr></thead><tbody>${lifecycleData.map((r,i)=>`<tr><td><div class="product-cell">${thumb(products[i].image,products[i].name)}<div><strong>${products[i].name}</strong><br><span class="subtle">${r[0]}</span></div></div></td>${r.slice(1,8).map((v,j)=>`<td class="${j===4?'delta':''}">${v}</td>`).join('')}<td>${tag(r[8],r[8]==='둔화'?'warning':'')}</td></tr>`).join('')}</tbody></table></div>`}
