function decisions(){
  if(state.backendMode==='connected'&&state.decisionWorkflowLoading&&!state.decisionWorkflowData)return '<div class="card panel operational-loading">추천과 결정 이력을 불러오는 중입니다.</div>';
  const data=state.decisionWorkflowData;if(!data){return `${kpi([['승인 대기','4건','검토 필요'],['수정 승인','1건','사유 기록'],['실행 요청','2건','후속 추적'],['학습 가능','0건','결과 대기']])}<div class="card panel"><h2>의사결정 워크플로</h2><p class="subtle">연결된 환경에서 AI 추천, 수정안 비교, 결정 사유와 실행 요청을 한 흐름으로 관리합니다.</p></div>`}
  const skuMap=new Map((data.skus||[]).map(row=>[String(row.id),row])),locationMap=new Map((data.locations||[]).map(row=>[String(row.id),row])),currentDecision=new Map((data.decisions||[]).filter(row=>row.is_current).map(row=>[String(row.recommendation_line_id),row])),seen=new Set(),lines=(data.lines||[]).filter(row=>{if(seen.has(row.recommendation_key))return false;seen.add(row.recommendation_key);return true}),pending=lines.filter(row=>!currentDecision.has(String(row.id))),selected=lines.find(row=>String(row.id)===String(state.decisionSelectedId))||pending[0]||lines[0];if(selected&&!state.decisionSelectedId)state.decisionSelectedId=selected.id;
  const cards=lines.map(row=>{const sku=skuMap.get(String(row.sku_id))||{},from=locationMap.get(String(row.from_location_id))||{},to=locationMap.get(String(row.to_location_id))||{},decision=currentDecision.get(String(row.id));return `<button class="decision-list-card ${String(row.id)===String(selected?.id)?'active':''}" data-decision-select="${escapeHtml(row.id)}"><span>${decision?decisionLabel(decision.decision):'결정 필요'}</span><strong>${escapeHtml(sku.sku_code||'SKU')} · ${escapeHtml(from.location_name||from.location_code||'공급처')} → ${escapeHtml(to.location_name||to.location_code||'수요처')}</strong><small>${Number(row.recommended_qty||0).toLocaleString()} pcs · 기대 순가치 ₩${Math.round(Number(row.expected_net_value||0)).toLocaleString()}</small></button>`}).join('');
  if(!selected)return '<div class="card panel operational-empty"><strong>검토할 재배치 추천이 없습니다.</strong><p>재고 계획을 실행하면 추천안이 이곳에 표시됩니다.</p><button class="btn" data-page="inventory">재고 운영으로 이동</button></div>';
  const sku=skuMap.get(String(selected.sku_id))||{},from=locationMap.get(String(selected.from_location_id))||{},to=locationMap.get(String(selected.to_location_id))||{},decision=currentDecision.get(String(selected.id)),recommended=Number(selected.recommended_qty||0),decided=Number(decision?.decided_qty??recommended),ratio=recommended?decided/recommended:0;
  return `${kpi([['결정 필요',`${pending.length}건`,'AI 추천 검토'],['결정 완료',`${currentDecision.size}건`,'원본과 별도 보존'],['실행 요청',`${(data.executions||[]).filter(row=>row.status==='requested').length}건`,'실행과 승인 분리'],['학습 가능',`${(data.outcomes||[]).filter(row=>row.learning_eligible).length}건`,'검증된 결과만']])}<div class="decision-workspace"><aside class="card decision-list"><header><strong>추천 안건</strong><button class="btn" id="refreshDecisionWorkflow">새로고침</button></header>${cards}</aside><section class="card decision-detail"><header><div><small>AI RECOMMENDATION</small><h2>${escapeHtml(sku.sku_code||'SKU')} 재고 이동</h2><p>${escapeHtml(from.location_name||from.location_code||'공급처')} → ${escapeHtml(to.location_name||to.location_code||'수요처')}</p></div>${tag(decision?decisionLabel(decision.decision):'결정 필요',decision?'':'warning')}</header><div class="decision-compare"><div><span>AI 추천</span><strong>${recommended.toLocaleString()} pcs</strong><small>순가치 ₩${Math.round(Number(selected.expected_net_value||0)).toLocaleString()}</small></div><div><span>현재 결정안</span><strong id="decisionPreviewQty">${decided.toLocaleString()} pcs</strong><small id="decisionPreviewValue">순가치 ₩${Math.round(Number(selected.expected_net_value||0)*ratio).toLocaleString()}</small></div></div><div class="decision-evidence"><div><span>목적지 부족량</span><b>${Number(selected.destination_shortage_qty||0).toLocaleString()} pcs</b></div><div><span>출발지 여유량</span><b>${Number(selected.source_excess_qty||0).toLocaleString()} pcs</b></div><div><span>예상 물류비</span><b>₩${Math.round(Number(selected.expected_logistics_cost||0)).toLocaleString()}</b></div><div><span>신뢰도</span><b>${Math.round(Number(selected.confidence||0)*100)||'—'}%</b></div></div><form id="decisionForm" class="decision-form" data-line-id="${escapeHtml(selected.id)}"><label>최종 수량<input id="decisionQuantity" type="number" min="0" step="1" value="${decided}"></label><label>희망 실행일<input id="decisionExecutionDate" type="date" value="${decision?.requested_execution_date||''}"></label><label>결정 사유<select id="decisionReason"><option value="">추천대로 승인</option>${[['destination_capacity','매장 수용량'],['inventory_difference','현장 재고 차이'],['promotion_plan','행사·프로모션'],['inbound_change','입고 일정 변경'],['logistics_constraint','물류 제약'],['cost_too_high','비용 과다'],['strategic_hold','전략적 재고 유지'],['forecast_uncertain','예측 신뢰도 부족'],['other','기타']].map(([value,label])=>`<option value="${value}" ${decision?.reason_code===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="wide">메모<textarea id="decisionNote" placeholder="현장에서 확인한 이유를 남겨주세요">${escapeHtml(decision?.note||'')}</textarea></label><div class="decision-actions"><button type="button" class="btn" data-decision-action="held">보류</button><button type="button" class="btn danger" data-decision-action="rejected">거절</button><button type="submit" class="btn primary" ${state.decisionWorkflowBusy?'disabled':''}>${decided===recommended?'추천대로 승인':'수정안 승인'}</button></div></form></section></div>`
}
function executionPerformance(){const data=state.decisionWorkflowData;if(state.backendMode==='connected'&&state.decisionWorkflowLoading&&!data)return '<div class="card panel operational-loading">실행과 성과 이력을 불러오는 중입니다.</div>';if(!data)return '<div class="card panel"><h2>실행·성과</h2><p class="subtle">승인된 결정의 실제 출고·입고와 결과를 추적합니다.</p></div>';const eventsByExecution=new Map();for(const event of data.events||[]){if(!eventsByExecution.has(event.execution_request_id))eventsByExecution.set(event.execution_request_id,[]);eventsByExecution.get(event.execution_request_id).push(event)}const active=(data.executions||[]).filter(row=>!['completed','cancelled','failed'].includes(row.status)),complete=(data.executions||[]).filter(row=>['completed','cancelled','failed'].includes(row.status)),rows=state.executionTab==='active'?active:complete;return `${kpi([['실행 대기',`${active.filter(row=>row.status==='requested').length}건`,'승인 후 실제 실행 전'],['진행 중',`${active.filter(row=>row.status!=='requested').length}건`,'출고·운송·입고'],['완료',`${complete.filter(row=>row.status==='completed').length}건`,'실행 확인'],['성과 평가',`${(data.outcomes||[]).length}건`,'D+7·14·28']])}<div class="execution-tabs"><button data-execution-tab="active" class="${state.executionTab==='active'?'active':''}">실행 현황</button><button data-execution-tab="complete" class="${state.executionTab==='complete'?'active':''}">완료·성과</button></div><div class="execution-grid">${rows.length?rows.map(row=>{const timeline=eventsByExecution.get(row.id)||[],outcomes=(data.outcomes||[]).filter(item=>item.execution_request_id===row.id);return `<article class="card execution-card"><header><div><span>${escapeHtml(row.execution_no)}</span><strong>${executionStatusLabel(row.status)}</strong></div>${tag(row.verification_method==='unverified'?'미확인':row.verification_method,row.verification_method==='unverified'?'warning':'')}</header><div class="execution-qty"><div><span>결정</span><b>${Number(row.requested_qty||0).toLocaleString()}</b></div><div><span>출고</span><b>${Number(row.executed_qty||0).toLocaleString()}</b></div><div><span>입고</span><b>${Number(row.received_qty||0).toLocaleString()}</b></div></div><div class="execution-timeline">${timeline.slice(0,4).map(event=>`<p><i></i><span>${escapeHtml(event.event_type)}</span><time>${String(event.occurred_at).slice(0,16).replace('T',' ')}</time></p>`).join('')||'<p>아직 실행 이벤트가 없습니다.</p>'}</div>${row.status==='requested'?`<button class="btn primary" data-execution-event="dispatched" data-execution-id="${row.id}" data-execution-qty="${row.requested_qty}">출고 확인</button>`:row.status==='in_progress'?`<button class="btn primary" data-execution-event="received" data-execution-id="${row.id}" data-execution-qty="${row.executed_qty||row.requested_qty}">입고 완료 확인</button>`:''}${outcomes.length?`<div class="outcome-slots">${outcomes.map(item=>`<span>D+${Math.round((new Date(item.measurement_end_date)-new Date(item.measurement_start_date))/86400000)} · ${item.outcome_status}</span>`).join('')}</div>`:''}</article>`}).join(''):'<div class="card panel operational-empty">해당 상태의 실행 요청이 없습니다.</div>'}</div>`}
