const discountMoney=value=>`₩${(Number(value||0)/1000000).toLocaleString(undefined,{maximumFractionDigits:1})}M`;
const discountTypeLabel=type=>({hold_price:'정상가 유지',reduce_discount:'할인 축소',maintain:'현 할인 유지',targeted_discount:'선별 할인'}[type]||'검토');
function profitabilityTabs(){return `<div class="profitability-tabs">${[['summary','수익성 요약'],['optimizer','최적 할인 추천'],['campaign','캠페인 효과 분석']].map(([id,label])=>`<button data-profitability-tab="${id}" class="${state.profitabilityTab===id?'active':''}">${label}</button>`).join('')}</div>`}
function discountCurve(row){const scenarios=Array.isArray(row.scenario_results)?row.scenario_results:[],max=Math.max(...scenarios.map(x=>Number(x.expected_contribution_margin||0)),1),points=scenarios.map((x,i)=>`${38+i*(524/Math.max(1,scenarios.length-1))},${180-Number(x.expected_contribution_margin||0)/max*125}`).join(' '),recommended=Number(row.recommended_discount_rate||0);return `<div class="optimizer-curve"><div class="curve-axis"><span>${discountMoney(max)}</span><span>${discountMoney(max/2)}</span><span>₩0</span></div><div><svg viewBox="0 0 600 205" preserveAspectRatio="none" role="img" aria-label="할인율별 예상 기여이익 곡선"><g>${[55,117,180].map(y=>`<line x1="30" y1="${y}" x2="570" y2="${y}"/>`).join('')}</g><polyline points="${points}"/>${scenarios.map((x,i)=>{const cx=38+i*(524/Math.max(1,scenarios.length-1)),cy=180-Number(x.expected_contribution_margin||0)/max*125,isBest=Number(x.discount_rate)===recommended;return `<circle class="${isBest?'best':''}" cx="${cx}" cy="${cy}" r="${isBest?7:4}"><title>${x.discount_rate}% · ${discountMoney(x.expected_contribution_margin)}</title></circle>${isBest?`<text x="${Math.max(20,cx-38)}" y="${Math.max(20,cy-14)}">권장 ${x.discount_rate}%</text>`:''}`}).join('')}</svg><div class="optimizer-x">${scenarios.map(x=>`<span>${x.discount_rate}%</span>`).join('')}</div></div></div>`}
function discountOptimizerDashboard(){const liveRows=state.discountIntelligence?.recommendations||[],rows=liveRows.length?liveRows:discountDemoRows,selected=rows.find(x=>String(x.recommendation_id)===String(state.discountSelectedId))||rows[0],canApprove=['owner','admin'].includes(state.currentUser?.backendRole)||['대표','전체 관리자'].includes(state.currentUser?.role),scenario=Array.isArray(selected?.scenario_results)?selected.scenario_results:[],approved=rows.filter(x=>x.decision_status==='approved').length,totalUplift=rows.reduce((sum,x)=>sum+Math.max(0,Number(x.contribution_uplift||0)),0),hold=rows.filter(x=>Number(x.recommended_discount_rate||0)<=5).length,source=liveRows.length?'저장된 계산 결과':'SAMPLE · 가정 기반';if(!selected)return '<div class="card panel">할인 추천 스냅샷이 없습니다.</div>';return `${kpi([['검토 추천안',`${rows.length}건`,`${approved}건 승인`],['예상 기여이익 개선',discountMoney(totalUplift),'14일 기준'],['0–5% 권장',`${hold}건`,'정상가·저할인 유지'],['계산 방식','6개 할인 구간','AI 재계산 없음']])}<section class="discount-optimizer"><header class="optimizer-head"><div><small>AX DISCOUNT OPTIMIZER</small><h2>매출이 아니라 기여이익과 잔여재고를 함께 최적화합니다</h2><p>상품 × 채널별로 0·5·10·15·20·30%를 계산하고, 비할인 대안이 더 유리하면 할인하지 않는 안을 추천합니다.</p></div><div><span>${source}</span>${canApprove?`<button class="btn" id="refreshDiscountIntelligence" ${state.discountRefreshing?'disabled':''}>${state.discountRefreshing?'계산 중…':'추천값 다시 계산'}</button>`:''}</div></header><div class="optimizer-layout"><div class="card panel optimizer-list"><div class="panel-title"><div><h2>상품·채널별 추천</h2><span class="subtle">기여이익 개선 가능성 순</span></div>${tag(`${rows.length}건`)}</div><div class="optimizer-items">${rows.map(x=>`<button data-discount-select="${escapeHtml(x.recommendation_id)}" class="${String(x.recommendation_id)===String(selected.recommendation_id)?'active':''}">${thumb((x.image_url||'').split('/').pop()||'9106213558.jpg',x.product_name)}<span><strong>${escapeHtml(x.product_code)} · ${escapeHtml(x.product_name)}</strong><small>${escapeHtml(x.channel_code)} · 현재 ${Number(x.current_discount_rate||0).toFixed(0)}%</small></span><b>${Number(x.recommended_discount_rate||0).toFixed(0)}%</b><em>${discountTypeLabel(x.recommendation_type)}</em></button>`).join('')}</div></div><div class="optimizer-detail"><div class="card panel optimizer-recommendation"><div class="optimizer-product"><div>${thumb((selected.image_url||'').split('/').pop()||'9106213558.jpg',selected.product_name)}<span><small>${escapeHtml(selected.channel_code)} · ${escapeHtml(selected.product_code)}</small><strong>${escapeHtml(selected.product_name)}</strong></span></div>${tag(discountTypeLabel(selected.recommendation_type),selected.recommendation_type==='targeted_discount'?'warning':'')}</div><div class="optimizer-answer"><span>AX 권장 할인율</span><strong>${Number(selected.recommended_discount_rate||0).toFixed(0)}%</strong><p>현재 ${Number(selected.current_discount_rate||0).toFixed(0)}% → 권장 ${Number(selected.recommended_discount_rate||0).toFixed(0)}% · 14일 적용</p></div><div class="optimizer-impact"><div><span>예상 판매</span><strong>${Number(selected.expected_quantity||0).toLocaleString()} pcs</strong></div><div><span>기여이익</span><strong>${discountMoney(selected.expected_contribution_margin)}</strong></div><div><span>개선 효과</span><strong>+${discountMoney(Math.max(0,selected.contribution_uplift))}</strong></div><div><span>종료 재고</span><strong>${Number(selected.ending_inventory_qty||0).toLocaleString()} pcs</strong></div></div><div class="optimizer-rationale"><strong>왜 이 값인가요?</strong><p>${escapeHtml(selected.rationale?.method_note||'가격 탄력성, 채널 비용, 재고커버와 잔여재고 위험을 함께 계산했습니다.')}</p><small>신뢰도 ${Math.round(Number(selected.confidence||0)*100)}% · 재고커버 ${Number(selected.inventory_cover_days||0).toFixed(1)}일</small></div><div class="optimizer-actions"><button class="btn" data-query="${escapeHtml(selected.product_code)} 할인 없이 소진할 방법을 알려줘">AX에 대안 질문</button><button class="btn" data-discount-decision="held" data-discount-id="${escapeHtml(selected.recommendation_id)}">보류</button><button class="btn primary" data-discount-decision="approved" data-discount-id="${escapeHtml(selected.recommendation_id)}" ${!canApprove||state.discountDecisionBusy?'disabled':''}>${selected.decision_status==='approved'?'승인됨':'추천안 승인'}</button></div></div><div class="card panel optimizer-chart-card"><div class="panel-title"><div><h2>할인율별 예상 기여이익</h2><span class="subtle">원가·수수료·물류비와 잔여재고 위험 반영</span></div>${semanticLegend([['예상 기여이익','var(--operations)'],['권장값','var(--target)']])}</div>${discountCurve(selected)}</div></div></div><div class="grid split optimizer-bottom"><div class="card panel"><div class="panel-title"><h2>할인 시나리오 비교</h2><span class="subtle">권장값이 항상 가장 높은 할인율은 아닙니다</span></div><table class="table"><thead><tr><th>할인율</th><th>예상 판매</th><th>예상 기여이익</th><th>종료 재고</th><th>판단</th></tr></thead><tbody>${scenario.map(x=>`<tr class="${Number(x.discount_rate)===Number(selected.recommended_discount_rate)?'recommended-row':''}"><td><strong>${x.discount_rate}%</strong></td><td>${Number(x.expected_quantity||0).toLocaleString()} pcs</td><td>${discountMoney(x.expected_contribution_margin)}</td><td>${Number(x.ending_inventory_qty||0).toLocaleString()} pcs</td><td>${Number(x.discount_rate)===Number(selected.recommended_discount_rate)?tag('AX 권장'):''}</td></tr>`).join('')}</tbody></table></div><div class="card panel non-discount-card"><div class="panel-title"><h2>할인 전에 실행할 대안</h2><span class="subtle">정상가 판매율 보호</span></div><div class="non-discount-primary"><span>우선 대안</span><strong>${escapeHtml(selected.non_discount_action||'노출 확대와 재고 이동을 우선 검토')}</strong></div><div class="non-discount-steps"><div><b>01</b><span><strong>재고 재배치</strong><small>과잉 위치 → 수요 위치</small></span></div><div><b>02</b><span><strong>노출·CRM 확대</strong><small>가격 인하 전 수요 자극</small></span></div><div><b>03</b><span><strong>선별 할인</strong><small>필요 채널·재고에만 적용</small></span></div></div><button data-query="${escapeHtml(selected.product_code)}의 재고 이동, CRM, 할인 중 가장 이익이 큰 안을 비교해줘">AX로 실행안 비교</button></div></div></section>`}
const discountOptimizerDashboardSample=discountOptimizerDashboard;
discountOptimizerDashboard=function(){if(state.backendMode==='connected'){if(state.discountLoading&&!state.discountIntelligence)return '<div class="card panel operational-loading">저장된 할인 최적화 결과를 불러오는 중입니다.</div>';if(!state.discountIntelligence?.recommendations?.length)return '<section class="card panel operational-empty"><strong>실제 할인 추천 결과가 아직 없습니다.</strong><p>비용 데이터가 준비되면 추천값 다시 계산을 실행해 상품 × 채널별 6개 할인 구간을 생성합니다.</p><button class="btn primary" id="refreshDiscountIntelligence">추천값 계산</button></section>'}return discountOptimizerDashboardSample()}
function campaignProfitabilityDashboard(){return `${campaignEffectAnalysis()}<div class="grid split"><div class="card panel"><div class="panel-title"><h2>캠페인별 수익성 판정</h2><span class="subtle">증분 기여이익 기준</span></div>${bars([['VIP CRM','iROAS 8.1x · 확대',92],['네이버 Live','6.2x · 유지',78],['ARC Drop','5.6x · 유지',69],['FW Brand Film','4.8x · 실험',54,'warning']])}</div><div class="card panel"><div class="panel-title"><h2>다음 실행</h2><span class="subtle">할인과 마케팅의 중복 효과 분리</span></div><div class="ai-list"><div><strong>VIP CRM 예산 +15%</strong><span>할인 없이 재구매 전환을 높이는 조합</span></div><div><strong>21:30 라이브 유지</strong><span>저녁 피크에서 추가 기여이익 ₩12.8M</span></div><div><strong>무신사 쿠폰 중복 제외</strong><span>광고·할인 중복 비용 ₩4.1M 절감 가능</span></div></div></div></div>`}
