hub=function(){if(state.backendMode==='connected'){if(state.dbOverviewLoading&&!state.dbOverview)return `<div class="card panel operational-loading">연결된 판매 데이터를 집계하고 있습니다.</div>`;return dbOverviewBlock()}const provenance='<div class="data-provenance sample"><strong>샘플 데이터</strong><span>데모용으로 생성된 값이며 고객 데이터와 혼합되지 않습니다.</span></div>';if(state.salesView!=='overview')return `${provenance}${salesTabs()}${state.salesView==='store'?storeView():state.salesView==='channel'?channelView():productView()}`;const headline=`<div class="grid kpis semantic-kpis">${[['오늘 순매출','₩482.6M','샘플 · +11.8%','4,20 18,15 32,17 46,9 60,11 76,4'],['판매수량','3,842 pcs','샘플 · +8.2%','4,18 18,20 32,13 46,15 60,8 76,6'],['주문수','3,116건','샘플 · +7.4%','4,19 18,16 32,18 46,12 60,9 76,7'],['객단가','₩154.9K','샘플 · +4.1%','4,17 18,14 32,15 46,12 60,10 76,9']].map(r=>`<div class="card kpi"><span class="label">${r[0]}</span><div class="value">${r[1]}</div><span class="delta">${r[2]}</span><svg class="kpi-spark" viewBox="0 0 80 24"><polyline points="${r[3]}"/></svg></div>`).join('')}</div>`;return `${provenance}${headline}${salesTabs()}${phaseOneSummary()+customerHubSummary()+phaseThreeSummary()}${hubOverviewV2()}`}
function targetBulletChart(){const rows=[['자사몰',82.6,100,105.2],['매장 POS',72.8,100,93.2],['무신사',83.0,100,101.6],['기타 온라인',74.9,100,95.8]];return `<div class="bullet-grid">${rows.map(r=>`<div class="bullet-row"><strong>${r[0]}</strong><div class="bullet-track"><i style="width:${r[1]/1.1}%"></i><em style="width:${r[2]/1.1}%"></em><b style="left:${r[2]/1.1}%"></b></div><span>${r[1]}%</span><div class="bullet-values"><span>현재</span><span>예상 ${r[3]}%</span><span>목표 100%</span></div></div>`).join('')}</div>`}
targetsV2=function(){return `<div class="scope-note target-scope"><div><strong>전사 월 마감 관리</strong><span>실제 매출, 목표 궤적과 보수·기준·공격 예측 범위를 한 화면에서 비교합니다.</span></div><button data-page="sales">제품 판매·생애주기 →</button></div>${kpi([['월 목표','₩6.20B','목표 100%'],['현재 매출','₩4.82B','달성률 77.7%'],['시간 진척률','68.4%','+9.3%p 선행'],['기준 예상','₩6.14B','목표 대비 -1.0%']])}<div class="grid forecast-layout"><div class="card panel fan-panel"><div class="panel-title"><div><h2>실제 매출 궤적 × 월말 예측 범위</h2><span class="subtle">8월 1–31일 · 누적 매출 ₩B</span></div>${semanticLegend([['실제','var(--sales-2)'],['목표','var(--target)','dashed'],['기준 예측','var(--forecast)','dashed'],['예측 범위','var(--forecast)','band']])}</div><div class="fan-chart"><div class="fan-y">${['₩6.5B','₩4.9B','₩3.3B','₩1.6B','₩0'].map(x=>`<span>${x}</span>`).join('')}</div><div class="fan-canvas"><svg viewBox="0 0 760 300" preserveAspectRatio="none" role="img" aria-label="월말 매출 예측 팬 차트"><defs><linearGradient id="fanGradient" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#7657d7" stop-opacity=".06"/><stop offset="1" stop-color="#7657d7" stop-opacity=".30"/></linearGradient></defs><g class="grid">${[20,85,150,215,280].map(y=>`<line x1="20" y1="${y}" x2="740" y2="${y}"/>`).join('')}</g><path class="fan" d="M400 95 L485 77 L570 56 L655 38 L740 22 L740 54 L655 65 L570 76 L485 87 L400 95 Z"/><path class="target-line" d="M20 280 L740 30"/><path class="actual-line" d="M20 267 L58 252 L96 238 L134 221 L172 207 L210 190 L248 174 L286 155 L324 139 L362 118 L400 95"/><path class="base-line" d="M400 95 L485 82 L570 68 L655 52 L740 34"/><line class="today" x1="400" y1="15" x2="400" y2="280"/><text x="407" y="286">오늘 · 8/20</text><text x="680" y="18">공격 6.48</text><text x="684" y="48">보수 5.86</text></svg><div class="x-axis">${['8/1','8/5','8/10','8/15','8/20','8/25','8/31'].map(x=>`<span>${x}</span>`).join('')}</div></div></div></div><div class="card panel"><div class="panel-title"><h2>월말 시나리오</h2><span class="subtle">실시간 재계산</span></div><div class="scenario-stack-v2">${[['보수적','₩5.86B','94.5% · Gap -₩340M',82],['기준','₩6.14B','99.0% · Gap -₩60M',94],['공격적','₩6.48B','104.5% · Upside +₩280M',100]].map((r,i)=>`<div class="scenario-v2 ${i===1?'selected':''}"><header><span>${r[0]}</span><strong>${r[1]}</strong></header><small>${r[2]}</small><em style="width:${r[3]}%"></em></div>`).join('')}</div><div class="phase3-callout"><strong>기준 시나리오는 목표에 1.0% 미달합니다.</strong><button data-query="공격적 시나리오의 필요 판매량은?">Gap 해소 분석</button></div></div></div><div class="grid split"><div class="card panel"><div class="panel-title"><h2>채널별 목표 기여 Bullet</h2><span class="subtle">현재 · 예상 · 목표</span></div>${targetBulletChart()}</div><div class="card panel"><div class="panel-title"><h2>조직별 월말 Gap</h2><span class="subtle">목표 대비 예상</span></div><div class="rank-bars">${[['자사몰','+₩80M','105.2%',88,''],['플랫폼 영업','+₩18M','101.6%',74,''],['중국 사업','-₩48M','95.6%',58,'down'],['오프라인 영업','-₩110M','93.2%',42,'down']].map((r,i)=>`<div class="rank-row"><span>${i+1}</span><strong>${r[0]}</strong><div class="rank-track"><i style="width:${r[3]}%;background:${r[4]?'var(--risk)':'var(--growth)'}"></i></div><div class="rank-value"><b>${r[1]}</b><small class="${r[4]}">${r[2]}</small></div></div>`).join('')}</div></div></div>`}
