inventoryOperationsDashboard=function(){if(state.inventoryTab!=='diagnosis')return legacyInventoryOperationsDashboard();const sku=[['ARC-07',76,28,58,'risk'],['FLOW-22',61,38,52,'risk'],['EASE-19',28,82,48,'over'],['CORE-08',39,62,42,'over'],['AIR-24',88,24,56,'risk'],['FRAME-31',22,86,44,'over'],['FORM-12',54,58,40,'']];const locations=[['강남','danger','danger','watch','safe','watch'],['성수','watch','safe','safe','safe','safe'],['온라인 DC','danger','watch','safe','safe','watch'],['상하이','watch','danger','safe','watch','safe'],['부산','danger','watch','watch','safe','safe']];return `${kpi([['품절 위험','38 SKU','7일 이내'],['과잉 재고','₩428M','46 SKU'],['이동 제안','18건','1,284 pcs'],['위험 매출','₩173M','4주 예상']])}<div class="inventory-tabs">${[['diagnosis','진단'],['actions','이동·재주문'],['inbound','입고·배송']].map(([id,label])=>`<button data-inventory-tab="${id}" class="${state.inventoryTab===id?'active':''}">${label}</button>`).join('')}</div><div class="grid inventory-viz-grid"><div class="card panel quadrant-panel"><div class="panel-title"><div><h2>판매속도 × 재고커버 사분면</h2><span class="subtle">버블 크기 = 4주 예상 매출 영향</span></div>${semanticLegend([['정상','var(--operations)'],['과잉','var(--target)'],['품절 위험','var(--risk)']])}</div><div class="quadrant"><div class="quadrant-y">재고 커버일수 ↑</div><div><div class="quadrant-plot"><span class="quadrant-label q1">저판매 · 충분재고</span><span class="quadrant-label q2">고판매 · 충분재고</span><span class="quadrant-label q3">저판매 · 부족재고</span><span class="quadrant-label q4">고판매 · 부족재고</span>${sku.map(r=>`<div class="sku-bubble ${r[4]}" style="--x:${r[1]}%;--y:${r[2]}%;--size:${r[3]}px" title="${r[0]}">${r[0]}</div>`).join('')}</div><div class="quadrant-x">일평균 판매속도 →</div></div></div></div><div class="card panel"><div class="panel-title"><div><h2>위치 × 제품 위험 Heatmap</h2><span class="subtle">커버일수와 판매속도 결합</span></div>${tag('LIVE')}</div><div class="risk-heatmap"><div></div>${['ARC-07','FLOW-22','EASE-19','CORE-08','AIR-24'].map(x=>`<div class="head">${x}</div>`).join('')}${locations.map(r=>`<div class="row">${r[0]}</div>${r.slice(1).map((c,i)=>`<div class="${c}">${c==='danger'?'긴급':c==='watch'?'주의':'정상'}</div>`).join('')}`).join('')}</div><div class="inventory-summary"><div><span>즉시 이동</span><strong>18건</strong></div><div><span>재주문 검토</span><strong>8건</strong></div><div><span>7일 내 품절</span><strong>38 SKU</strong></div><div><span>과잉 재고</span><strong>₩428M</strong></div></div><div class="phase3-callout"><strong>ARC-07·AIR-24가 고판매·부족재고 구간입니다.</strong><button data-inventory-tab="actions">조치 보기</button></div></div></div><div class="card panel inventory-table-panel"><div class="panel-title"><h2>긴급 SKU 상세</h2><span class="subtle">그래프의 이상값만 우선 표시</span></div><table class="table"><thead><tr><th>제품</th><th>핵심 위치</th><th>일 판매</th><th>가용재고</th><th>커버</th><th>위험 매출</th><th>권장 행동</th></tr></thead><tbody>${[['ARC-07','강남점','63 pcs','504 pcs','8.0일','₩42M','매장 이동'],['AIR-24','29CM','29 pcs','216 pcs','7.4일','₩38M','재주문'],['FLOW-22','부산 센텀','42 pcs','486 pcs','11.6일','₩86M','이동 + 재주문']].map((r,i)=>`<tr><td><div class="product-cell">${thumb(productImages[i],r[0])}<strong>${r[0]}</strong></div></td>${r.slice(1,6).map(v=>`<td>${v}</td>`).join('')}<td>${tag(r[6],'danger')}</td></tr>`).join('')}</tbody></table></div>`}
function profitabilityWaterfall(){const cols=[['순매출','₩1,066M',0,100,'start'],['원가','-₩358M',66,34,'cost'],['채널비','-₩114M',55,11,'cost'],['광고','-₩67M',49,6,'cost'],['배송·반품','-₩19M',47,2,'cost'],['기여이익','₩508M',0,48,'end']];return `<div class="waterfall-chart"><div class="waterfall-y">${['₩1,100M','₩825M','₩550M','₩275M','₩0'].map(x=>`<span>${x}</span>`).join('')}</div><div><div class="waterfall-canvas">${cols.map(r=>`<div class="waterfall-col ${r[4]}" style="--bottom:${r[2]}%;--height:${r[3]}%"><i></i><b>${r[1]}</b><span>${r[0]}</span></div>`).join('')}</div></div></div><div class="waterfall-foot">매출에서 실제 변동비를 순차 차감한 기여이익 구조</div>`}
function profitabilityBubble(){const rows=[['국내매장',138,61.6,62,'high'],['중국매장',133,60.4,60,'high'],['자사몰',138,53.4,58,'high'],['네이버',134,47.4,56,''],['라이브',147,42.3,64,'low'],['W컨셉',132,40.4,54,'low'],['29CM',117,39.1,50,'low'],['무신사',128,34.7,53,'low']];return `<div class="bubble-chart"><span class="bubble-axis-y">기여이익률 ↑</span><span class="bubble-axis-x">순매출 규모 →</span>${rows.map(r=>`<div class="profit-bubble ${r[4]}" style="--x:${12+(r[1]-115)*2.35}%;--y:${10+(r[2]-32)*2.5}%;--size:${r[3]}px" title="${r[0]} · ₩${r[1]}M · ${r[2]}%"><strong>${r[0]}</strong><small>${r[2]}%</small></div>`).join('')}</div>`}
profitabilityDashboardV2=function(){const channels=[['국내매장','₩137.9M','61.6%','확대'],['중국매장','₩132.8M','60.4%','확대'],['자사몰','₩138.2M','53.4%','확대'],['네이버','₩134.0M','47.4%','유지'],['라이브커머스','₩146.9M','42.3%','효율 점검'],['W컨셉','₩131.6M','40.4%','수수료 점검'],['29CM','₩117.2M','39.1%','할인 점검'],['무신사','₩127.8M','34.7%','할인·수수료 점검']];return `${kpi([['실현 순매출','₩1.066B','8,033 orders'],['기여이익','₩508.0M','이익률 47.6%'],['최고 이익률','61.6%','국내매장'],['평균 할인율','7.6%','할인액 ₩91.1M']])}<div class="grid profit-viz-grid"><div class="card panel"><div class="panel-title"><div><h2>순매출 → 기여이익 Waterfall</h2><span class="subtle">상품원가·채널비·광고·배송/반품 순차 차감</span></div>${semanticLegend([['매출','var(--sales-2)'],['비용','var(--risk)'],['기여이익','var(--operations)']])}</div>${profitabilityWaterfall()}</div><div class="card panel"><div class="panel-title"><div><h2>채널 매출 × 이익률 포지션</h2><span class="subtle">버블 크기 = 순매출</span></div>${semanticLegend([['고수익','var(--operations)'],['평균','var(--sales)'],['저수익','var(--risk)']])}</div>${profitabilityBubble()}</div></div>${campaignEffectAnalysis()}<div class="grid split"><div class="card panel"><div class="panel-title"><div><h2>할인율 × 이익률·반품률 곡선</h2><span class="subtle">할인이 깊어질수록 이익률 하락·반품률 상승</span></div>${semanticLegend([['이익률','var(--operations)'],['반품률','var(--risk)','dashed']])}</div><div class="discount-curve"><div class="curve-y">${['60%','45%','30%','15%','0%'].map(x=>`<span>${x}</span>`).join('')}</div><div><svg viewBox="0 0 500 190" preserveAspectRatio="none"><g class="grid">${[10,55,100,145,188].map(y=>`<line x1="8" y1="${y}" x2="492" y2="${y}"/>`).join('')}</g><polyline class="margin" points="35,28 180,66 325,84 465,105"/><polyline class="return" points="35,166 180,156 325,149 465,139"/>${[[35,28],[180,66],[325,84],[465,105]].map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="var(--operations)"/>`).join('')}${[[35,166],[180,156],[325,149],[465,139]].map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="var(--risk)"/>`).join('')}</svg><div class="discount-x">${['0–5%','5–10%','10–15%','15%+'].map(x=>`<span>${x}</span>`).join('')}</div></div></div><div class="phase3-callout"><strong>15%+ 할인 구간은 이익률이 전사 평균보다 12.9%p 낮습니다.</strong><button data-query="할인율을 낮춰도 판매량을 유지할 제품은?">제품 찾기</button></div></div><div class="card panel"><div class="panel-title"><h2>채널별 조치 우선순위</h2><span class="subtle">매출 규모와 이익률 동시 판단</span></div><table class="table"><thead><tr><th>채널</th><th>순매출</th><th>이익률</th><th>판단</th></tr></thead><tbody>${channels.map((r,i)=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td class="${i>4?'delta down':''}"><strong>${r[2]}</strong></td><td>${tag(r[3],i>4?'warning':'')}</td></tr>`).join('')}</tbody></table></div></div>`}
const profitabilitySummaryViewFinal=profitabilityDashboardV2;
function profitabilityDataRequired(){const d=state.profitabilityDbData?.readiness||{},cost=Number(d.costCoveragePct||0).toFixed(1),variable=Number(d.variableCostCoveragePct||0).toFixed(1);return `<div class="data-provenance stale"><strong>비용 데이터 필요</strong><span>원가 커버리지 ${cost}% · 채널/광고/배송/반품비 커버리지 ${variable}%</span><button class="btn" data-page="connections">비용 포함 판매 파일 연결</button></div><section class="card panel operational-empty profitability-gate"><strong>실제 수익성 수치를 표시하지 않았습니다.</strong><p>순매출만으로 이익을 추정하면 잘못된 할인 결정을 만들 수 있습니다. 판매 CSV에 개당원가와 채널수수료·마케팅비·배송비·반품처리비를 추가하면 수익성 요약과 최적 할인 추천이 활성화됩니다.</p><a class="btn primary" href="./assets/templates/VIIMsignal_Sales_Import_Template.csv" download>비용 컬럼 포함 템플릿 받기</a></section>`}
function profitabilityLiveSummary(){const d=state.profitabilityDbData||{},s=d.summary||{},channels=d.channels||[],products=d.products||[],money=value=>`₩${(Number(value||0)/1000000).toLocaleString(undefined,{maximumFractionDigits:1})}M`,margin=value=>Number(value||0).toFixed(1),best=[...channels].sort((a,b)=>Number(b.contribution_margin||0)/Math.max(Number(b.net_sales||0),1)-Number(a.contribution_margin||0)/Math.max(Number(a.net_sales||0),1))[0],maxSales=Math.max(...channels.map(row=>Number(row.net_sales||0)),1);return `<div class="data-provenance connected"><strong>실제 수익성 데이터</strong><span>최근 ${Number(d.periodDays||60)}일 · 원가 ${margin(d.readiness?.costCoveragePct)}% · 변동비 ${margin(d.readiness?.variableCostCoveragePct)}% 커버</span></div>${kpi([['실현 순매출',money(s.netSales),'운영 DB 집계'],['기여이익',money(s.contributionMargin),`이익률 ${margin(s.marginRate)}%`],['집계 비용',money(s.costs),'원가·수수료·마케팅·물류'],['최고 이익률 채널',escapeHtml(best?.label||'—'),best?`${margin(Number(best.contribution_margin||0)/Math.max(Number(best.net_sales||0),1)*100)}%`:'데이터 없음']])}<div class="grid split"><section class="card panel"><div class="panel-title"><div><h2>채널별 실제 기여이익률</h2><span class="subtle">순매출 규모와 비용 차감 후 이익</span></div>${tag('LIVE')}</div><div class="rank-bars">${channels.map((row,index)=>{const sales=Number(row.net_sales||0),cm=Number(row.contribution_margin||0),rate=sales?cm/sales*100:0;return `<div class="rank-row"><span>${index+1}</span><strong>${escapeHtml(row.label)}</strong><div class="rank-track"><i style="width:${Math.max(4,sales/maxSales*100)}%"></i></div><div class="rank-value"><b>${money(cm)}</b><small class="${rate<20?'down':''}">${margin(rate)}%</small></div></div>`}).join('')||'<div class="operational-empty compact">판매 데이터가 없습니다.</div>'}</div></section><section class="card panel"><div class="panel-title"><div><h2>상품별 기여이익</h2><span class="subtle">최근 60일 실제 판매 라인 기준</span></div></div><table class="table"><thead><tr><th>상품</th><th>순매출</th><th>기여이익</th><th>이익률</th></tr></thead><tbody>${products.slice(0,12).map(row=>{const sales=Number(row.net_sales||0),cm=Number(row.contribution_margin||0);return `<tr><td><strong>${escapeHtml(row.label)}</strong></td><td>${money(sales)}</td><td>${money(cm)}</td><td><strong>${margin(sales?cm/sales*100:0)}%</strong></td></tr>`}).join('')||'<tr><td colspan="4">상품별 판매 데이터가 없습니다.</td></tr>'}</tbody></table></section></div>`}
