function axVisual(c){if(c.visual==='matrix')return `<div class="ax-matrix" data-y="${state.page==='planning'?'자사 경쟁력 ↑':'재고커버 ↑'}" data-x="${state.page==='planning'?'시장 수요 →':'판매속도 →'}">${c.points.map(p=>`<span class="ax-point ${p[3]||''}" style="--x:${p[1]};--y:${p[2]}">${p[0]}</span>`).join('')}</div>`;if(c.visual==='timeline')return `<div class="ax-time-axis"><span></span>${['W1','W2','W3','W4'].map(x=>`<span>${x}</span>`).join('')}</div><div class="ax-timeline">${c.rows.map(r=>`<div class="ax-time-row ${r[4]||''}"><strong>${r[0]}</strong><div class="ax-time-track"><i style="--start:${r[1]}%;--w:${r[2]}%"></i></div><span>${r[3]}</span></div>`).join('')}</div>`;if(c.visual==='daily')return `<div class="ax-daily"><span class="ax-daily-label">실제·전년·예측</span>${['월','화','수','목','금','토','일'].map((d,i)=>`<div class="ax-day">${c.series.map(s=>`<i style="--h:${s[i]}%"></i>`).join('')}<span>${d}</span></div>`).join('')}</div>`;if(c.visual==='rank')return `<div class="ax-rank-list">${c.rows.map(r=>`<div class="ax-rank-row ${r[4]||''}"><span>${r[1]}</span><strong>${r[0]}</strong><span>${r[2]}</span><b>${r[3]}</b></div>`).join('')}</div>`;return `<div class="ax-result-bars">${c.rows.map(r=>`<div class="ax-result-bar ${r[3]||''}"><span>${r[0]}</span><i><em style="--w:${r[1]}%"></em></i><b>${r[2]}</b></div>`).join('')}</div>`}
