function axCommand(){const c=currentAxConfig(),list=prompts[state.page]||[c.query,'현재 페이지의 이상 신호를 찾아줘','다음 실행 행동을 추천해줘'];const status=state.axBusy?'AX가 데이터를 분석 중…':state.axError?'분석을 완료하지 못했습니다':state.axApproved?'승인 완료 · 작업 큐에 전달':state.aiResult?(state.axMode==='detail'?'상세 분석 워크스페이스':'분석 완료 · 실행안 확인'):'Enter로 분석 실행';return `<div class="ax-command-shell"><form class="ax-command-bar" id="axForm"><button class="ax-mark" type="button" id="axMark">AX</button><label class="ax-input-wrap"><input id="axQuestion" aria-label="AX 질문" autocomplete="off" value="${axEscape(state.aiQuery)}" placeholder="AX에게 질문하거나 실행을 요청하세요" ${state.axBusy?'disabled':''}><kbd>⌘ K</kbd></label><button class="ax-history-button" type="button" id="axHistoryButton">대화 기록</button><button class="ax-command-state ${state.axBusy?'busy':''} ${state.axError?'error':''} ${state.aiResult?'done':''} ${state.axApproved?'approved':''}" type="submit" ${state.axBusy?'disabled':''}>${status}</button></form>${state.axError?`<div class="ax-request-error" role="alert"><strong>AX 연결 확인 필요</strong><span>${escapeHtml(state.axError)}</span></div>`:''}${state.axHistoryOpen?axHistoryPanel():''}<div class="ax-suggestions"><div class="ax-suggest-head"><strong>현재 데이터에 맞춴 추천 질문</strong><span>${pageMeta[state.page][0]} · ${state.country}</span></div><div class="ax-suggestion-grid">${list.slice(0,3).map(q=>`<button class="ax-suggestion" data-ax-query="${axEscape(q)}">${q}</button>`).join('')}</div></div></div>`}
function axHistoryPanel(){const conversations=state.axHistory||[],messages=state.axMessages||[];return `<aside class="ax-history-panel"><header><div><strong>내 AX 대화</strong><small>회사와 사용자 계정별로 저장됩니다</small></div><button type="button" id="axNewConversation">새 대화</button></header><div class="ax-history-layout"><nav>${conversations.length?conversations.map(c=>`<button type="button" data-conversation="${c.id}" class="${c.id===state.activeConversationId?'active':''}"><strong>${escapeHtml(c.title)}</strong><small>${escapeHtml(pageMeta[c.page_key]?.[0]||c.page_key)} · ${new Date(c.last_message_at).toLocaleDateString('ko-KR')}</small></button>`).join(''):'<p>아직 저장된 대화가 없습니다.</p>'}</nav><div class="ax-message-list">${messages.length?messages.map(m=>`<article class="${m.role}"><p>${escapeHtml(m.content)}</p></article>`).join(''):'<div class="ax-empty-chat">대화를 선택하거나 새 질문을 입력하세요.</div>'}</div></div></aside>`}
function axDemoStorageKey(){return `fashionAxThreads:${state.currentUser?.email||'demo'}`}
function readDemoThreads(){try{return JSON.parse(localStorage.getItem(axDemoStorageKey())||'[]')}catch{return []}}
function writeDemoThreads(threads){localStorage.setItem(axDemoStorageKey(),JSON.stringify(threads.slice(0,30)))}
function hydrateDemoHistory(conversationId=null){const threads=readDemoThreads();state.axHistory=threads.map(({messages,...thread})=>thread);const active=threads.find(thread=>thread.id===(conversationId||state.activeConversationId))||threads[0];state.activeConversationId=active?.id||null;state.axMessages=active?.messages||[]}
function saveDemoTurn(question,answer){const now=new Date().toISOString(),threads=readDemoThreads();let thread=threads.find(item=>item.id===state.activeConversationId);if(!thread){thread={id:`demo-${Date.now()}`,title:question.slice(0,80),page_key:state.page,last_message_at:now,created_at:now,messages:[]};threads.unshift(thread)}thread.page_key=state.page;thread.last_message_at=now;thread.messages.push({id:`u-${Date.now()}`,role:'user',content:question,page_key:state.page,created_at:now},{id:`a-${Date.now()+1}`,role:'assistant',content:answer,page_key:state.page,source:'demo',created_at:now});writeDemoThreads([thread,...threads.filter(item=>item.id!==thread.id)]);hydrateDemoHistory(thread.id)}
function axNarrative(c){return `${c.title}. ${c.actions?.[0]?.[0]||'우선 실행안'}을 먼저 검토하면 ${c.impact?.[0]?.[1]||'예상 효과'}를 기대할 수 있습니다.`}
function axContextLabel(){return `${currentBrandWorkspace().name} · ${pageMeta[state.page][0]} · ${state.country} · ${state.channel}`}
function axContextItems(){const context=state.axContext;if(!context)return [];const metricLabels={net_sales:'순매출',quantity:'판매수량',orders:'주문수',available_qty:'가용재고',inventory_cover_days:'재고커버',contribution_margin:'기여이익',return_rate:'반품률',sell_through_rate:'판매율',forecast:'수요예측',discount:'할인추천',review_signal:'리뷰 신호',customer:'고객',returns:'반품·취소',production:'생산'},dimensionLabels={day:'일별',channel:'채널별',location:'매장·지역별',product:'제품별',brand:'브랜드별',platform:'플랫폼별',category:'카테고리별',market_product:'외부상품별',production_order:'생산오더별'},items=[];if(context.periodDays)items.push(['periodDays',`최근 ${context.periodDays}일`]);if(context.metric)items.push(['metric',metricLabels[context.metric]||context.metric]);if(context.dimension)items.push(['dimension',dimensionLabels[context.dimension]||context.dimension]);Object.entries(context.filters||{}).forEach(([key,value])=>{if(value)items.push([key,String(value)])});if(context.comparison)items.push(['comparison',context.comparison==='previous_year'?'전년 동기 비교':'이전 기간 비교']);return items.slice(0,8)}
function axContextStrip(){const items=axContextItems();if(!items.length)return '';const inherited=new Set(state.axInherited||[]);return `<div class="ax-context-strip"><div><span>현재 분석 문맥</span><button type="button" id="axContextReset">조건 초기화</button></div><div class="ax-context-chips">${items.map(([field,label])=>`<button type="button" data-ax-context-remove="${field}" class="${inherited.has(field)?'inherited':''}" title="${escapeHtml(label)} 조건 제거"><span>${escapeHtml(label)}</span><i>×</i></button>`).join('')}</div>${state.axInherited?.length?`<small>이전 분석에서 ${state.axInherited.length}개 조건을 이어받았습니다.</small>`:''}</div>`}
function axPanelAnalysis(){if(!state.aiResult)return '';const c=currentAxConfig();return `<section class="ax-panel-analysis"><div class="ax-panel-analysis-head"><span>${escapeHtml(c.eyebrow)}</span><small>${escapeHtml(c.fresh)}</small></div><h3>${escapeHtml(c.title)}</h3><div class="ax-panel-facts">${(c.impact||[]).slice(0,3).map(item=>`<div><span>${escapeHtml(item[0])}</span><strong>${escapeHtml(item[1])}</strong></div>`).join('')}</div><div class="ax-panel-mini-viz"><div class="ax-panel-mini-title"><strong>${escapeHtml(c.chartTitle)}</strong><small>${escapeHtml(c.chartSub)}</small></div>${axVisual(c)}</div><div class="ax-panel-evidence"><span>판단 근거</span><p>${escapeHtml(c.basis)}</p>${state.axEvidence?`<small>마지막 동기화 23:59 KST · ${escapeHtml(state.country)} · ${escapeHtml(state.channel)} · 현재 계정 권한 범위</small>`:''}</div><div class="ax-panel-recommendations">${(c.actions||[]).slice(0,3).map((action,index)=>`<article class="${state.axSelectedAction===index?'selected':''}"><span>0${index+1}</span><div><strong>${escapeHtml(action[0])}</strong><small>${escapeHtml(action[1])}</small>${action[3]?`<button type="button" data-ax-select-action="${index}">${state.axSelectedAction===index?'실행안 선택됨':'이 실행안 검토'}</button>`:''}</div><b>${escapeHtml(action[2])}</b></article>`).join('')}</div><div class="ax-panel-response-actions"><button type="button" data-ax-evidence>${state.axEvidence?'근거 접기':'근거 보기'}</button><button type="button" data-ax-adjust>수량·조건 조정</button><button type="button" class="primary" data-ax-approve>${state.axApproved?'승인 완료':escapeHtml(c.cta)}</button></div>${state.axActionStatus?`<p class="ax-action-status">${state.axActionStatus==='approved'?'승인되어 담당 팀 실행 큐에 전달되었습니다.':state.axActionStatus==='executing'?'실제 실행 큐를 생성하고 있습니다…':'조정 요청을 이어서 입력해주세요.'}</p>`:''}</section>`}
function axConversationView(){const messages=state.axMessages||[],suggestions=state.page==='customers'&&state.customerTab==='reviews'?['최근 부정 리뷰가 급증한 상품과 원인을 보여줘','반품 위험과 함께 나타나는 리뷰 주제를 분석해줘','디자인·생산·CS팀이 오늘 처리할 리뷰 액션을 정리해줘']:(prompts[state.page]||[currentAxConfig().query,'현재 페이지의 이상 신호를 찾아줘','다음 실행 행동을 추천해줘']);return `<div class="ax-conversation-scroll" id="axConversationScroll">${axContextStrip()}${messages.length?messages.map(message=>`<div class="ax-message ${message.role==='user'?'user':'assistant'}"><p>${escapeHtml(message.content)}</p></div>`).join(''):`<div class="ax-welcome"><span>AX</span><h3>${escapeHtml(pageMeta[state.page][0])}에서 무엇을 확인할까요?</h3><p>현재 페이지와 권한 범위의 데이터를 함께 읽고, 근거와 다음 행동까지 제안합니다.</p></div>`}${state.axBusy?`<div class="ax-thinking"><i></i><span>${escapeHtml(state.axPhase||'판매·재고·운영 데이터를 분석하고 있습니다')}</span></div>`:''}${state.axError?`<div class="ax-panel-error"><strong>AX 연결 확인 필요</strong><span>${escapeHtml(state.axError)}</span></div>`:''}${state.axWarning?`<div class="ax-panel-warning"><strong>빠른 지표 분석으로 완료</strong><span>${escapeHtml(state.axWarning)}</span></div>`:''}${state.axElapsedMs!=null&&!state.axBusy?`<div class="ax-response-speed">${state.axElapsedMs<1000?'즉시 응답':`${(state.axElapsedMs/1000).toFixed(1)}초`} · ${state.axDynamic?.source==='cache'?'캐시':'권한 범위 데이터'} 기반</div>`:''}${axPanelAnalysis()}${!messages.length&&!state.aiResult?`<div class="ax-starter-prompts">${suggestions.slice(0,3).map(question=>`<button type="button" data-ax-query="${axEscape(question)}">${escapeHtml(question)}</button>`).join('')}</div>`:''}</div>`}
function axHistoryView(){const conversations=state.axHistory||[],empty=state.backendMode==='connected'&&!state.axHistoryLoaded?'대화 기록을 불러오는 중입니다.':'아직 저장된 대화가 없습니다.';return `<div class="ax-panel-history"><div class="ax-history-heading"><div><strong>대화 기록</strong><small>회사·사용자 계정별로 저장됩니다</small></div><button type="button" id="axNewConversation">＋ 새 대화</button></div>${conversations.length?conversations.map(conversation=>`<button type="button" class="ax-history-row ${conversation.id===state.activeConversationId?'active':''}" data-conversation="${conversation.id}"><span>${escapeHtml(pageMeta[conversation.page_key]?.[0]||conversation.page_key)}</span><strong>${escapeHtml(conversation.title)}</strong><small>${new Date(conversation.last_message_at).toLocaleString('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></button>`).join(''):`<div class="ax-history-empty">${empty}</div>`}</div>`}
function axVoiceLabel(){return state.axVoiceState==='listening'?'듣고 있어요 · 다시 누르면 중지':state.axVoiceState==='speaking'?'AX가 말하고 있어요 · 누르면 중지':state.axVoiceState==='unsupported'?'이 브라우저는 음성 입력을 지원하지 않아요':'마이크를 눌러 말해보세요'}
function axPushPanel(stable=false){if(!state.ai)return '';const voiceActive=['listening','speaking'].includes(state.axVoiceState);return `<aside class="ax-push-panel ${stable?'ax-panel-stable':''}" aria-label="VIIM AX"><header class="ax-panel-header"><div><span class="ax-panel-brand ${voiceActive?'voice-active':''}">AX</span><div><strong>VIIM AX</strong><small>${escapeHtml(axContextLabel())}</small></div></div><button type="button" id="axPanelClose" aria-label="VIIM AX 패널 닫기">×</button></header><div class="ax-panel-tabs"><button type="button" data-ax-tab="chat" class="${state.axPanelTab==='chat'?'active':''}">현재 대화</button><button type="button" data-ax-tab="history" class="${state.axPanelTab==='history'?'active':''}">기록 ${state.axHistory.length||''}</button></div>${state.axPanelTab==='history'?axHistoryView():axConversationView()}<form class="ax-composer" id="axPanelForm"><div class="ax-voice-status ${voiceActive?'active':''}" aria-live="polite"><i></i><span>${axVoiceLabel()}</span></div><div class="ax-composer-row"><button class="ax-voice-button ${state.axVoiceState==='listening'?'listening':''}" type="button" id="axVoiceButton" aria-label="${state.axVoiceState==='listening'?'음성 입력 중지':'음성으로 질문하기'}" title="음성으로 질문하기">${state.axVoiceState==='listening'?'■':'●'}</button><textarea id="axPanelQuestion" aria-label="AX 질문" rows="1" placeholder="오늘 무엇을 결정해야 하나요?" ${state.axBusy?'disabled':''}></textarea><div><span>⌘ + Enter</span><button type="submit" ${state.axBusy?'disabled':''} aria-label="질문 보내기">↑</button></div></div></form></aside>`}
function axTopLauncher(){return `<button type="button" class="ax-top-launcher ${state.ai?'active':''}" id="axTopLauncher"><span>AX</span><strong>${state.ai?'VIIM AX 열림':'VIIM AX'}</strong><kbd>⌘K</kbd></button>`}
function syncAxLauncher(){const launcher=document.querySelector('#axTopLauncher');if(!launcher)return;launcher.classList.toggle('active',state.ai);const label=launcher.querySelector('strong');if(label)label.textContent=state.ai?'VIIM AX 열림':'VIIM AX'}
function resizeAxComposer(field=document.querySelector('#axPanelQuestion')){if(!field)return;field.style.height='auto';field.style.height=`${Math.min(120,Math.max(44,field.scrollHeight))}px`}
function refreshAxPanel(options={}){const app=document.querySelector('.app');if(!app||!state.authenticated){render();return}const draft=document.querySelector('#axPanelQuestion')?.value||'',current=app.querySelector('.ax-push-panel'),previousScroll=current?.querySelector('#axConversationScroll'),wasNearBottom=previousScroll?previousScroll.scrollHeight-previousScroll.scrollTop-previousScroll.clientHeight<48:true,previousScrollTop=previousScroll?.scrollTop||0;app.classList.toggle('ax-panel-open',state.ai);if(!state.ai){current?.remove();app.querySelector('.ax-modal-backdrop')?.remove();syncAxLauncher();return}const panelHtml=axPushPanel(Boolean(current));if(current)current.outerHTML=panelHtml;else app.insertAdjacentHTML('beforeend',panelHtml);app.querySelector('.ax-modal-backdrop')?.remove();const modal=axApprovalModal();if(modal)app.insertAdjacentHTML('beforeend',modal);syncAxLauncher();bindAxPanelControls();const input=document.querySelector('#axPanelQuestion'),nextScroll=document.querySelector('#axConversationScroll');if(input&&options.preserveDraft!==false&&draft)input.value=draft;resizeAxComposer(input);if(nextScroll){const shouldFollow=options.scroll||wasNearBottom;nextScroll.scrollTop=shouldFollow?nextScroll.scrollHeight:Math.min(previousScrollTop,nextScroll.scrollHeight)}requestAnimationFrame(()=>{if(options.scroll&&options.smooth===true)nextScroll?.scrollTo({top:nextScroll.scrollHeight,behavior:'smooth'});if(options.focus)input?.focus()})}
function updateAxPhase(message){state.axPhase=message;const label=document.querySelector('.ax-thinking span');if(label){label.textContent=message;return}refreshAxPanel({scroll:true,smooth:false})}
function openAxPanel(){state.ai=true;state.axPanelTab='chat';if(state.backendMode!=='connected')hydrateDemoHistory();refreshAxPanel({focus:true,scroll:true})}
function closeAxPanel(){stopAxVoice();state.ai=false;refreshAxPanel()}
function workspaceRailMark(brand){return brand.imageUrl?`<img src="${escapeHtml(brand.imageUrl)}" alt="">`:`<svg class="workspace-default-mark" viewBox="0 0 32 32" aria-hidden="true"><path d="M16 3 29 10.5 16 18 3 10.5 16 3Z"/><path d="m3 16 13 7.5L29 16"/><path d="m3 21.5 13 7.5 13-7.5"/></svg>`}
function workspaceRail(){const active=currentBrandWorkspace(),brands=brandWorkspaces(),canManage=['owner','admin'].includes(state.currentUser?.backendRole)||['대표','전체 관리자'].includes(state.currentUser?.role);return `<aside class="workspace-rail" aria-label="브랜드 워크스페이스"><div class="workspace-top">${brands.map(brand=>`<button type="button" class="workspace-item ${brand.id===active.id?'active':''} ${brand.available?'':'unavailable'}" data-brand-workspace="${escapeHtml(brand.id)}" ${brand.available?'':`disabled aria-disabled="true"`} aria-label="${escapeHtml(brand.name)} 워크스페이스" title="${escapeHtml(brand.available?`${brand.name} 워크스페이스${brand.id===active.id?' · 메뉴 열기':''}`:`${brand.name} · 사용할 수 없음`)}">${workspaceRailMark(brand)}${brand.isTest?'<i aria-hidden="true"></i>':brand.available?'':'<i class="unavailable-dot" aria-hidden="true"></i>'}</button>`).join('')}${canManage?'<button type="button" class="workspace-control workspace-add" id="workspaceAdd" aria-label="새 워크스페이스 만들기" title="새 워크스페이스 만들기">＋</button>':''}</div>${state.workspaceMenuOpen?`<div class="workspace-popover"><div class="workspace-popover-profile">${active.imageUrl?`<img src="${escapeHtml(active.imageUrl)}" alt="">`:`<strong>${escapeHtml(active.code)}</strong>`}<span><b>${escapeHtml(active.name)}</b><small>${escapeHtml(active.description||'워크스페이스 설명이 없습니다.')}</small></span></div>${canManage&&active.source==='workspace'?'<button type="button" id="workspaceSettingsOpen">워크스페이스 프로필 및 설정</button>':''}<button type="button" id="workspaceMenuClose">메뉴 닫기</button></div>`:''}<div class="workspace-bottom"><span class="workspace-divider"></span><button type="button" class="workspace-account" title="내 계정">${escapeHtml((state.currentUser?.name||'사용자').slice(0,1))}</button></div></aside>`}
function workspaceCreateModal(){if(!state.workspaceCreateOpen)return '';const brands=state.currentUser?.brands||[];return `<div class="workspace-modal-backdrop" id="workspaceModalBackdrop"><section class="workspace-modal" role="dialog" aria-modal="true" aria-labelledby="workspaceModalTitle"><header><div><span>NEW WORKSPACE</span><h2 id="workspaceModalTitle">새 워크스페이스 만들기</h2><p>별도의 데이터와 의사결정 흐름을 운영할 공간을 만듭니다.</p></div><button type="button" id="workspaceCreateClose" aria-label="닫기">×</button></header><form id="workspaceCreateForm"><label>워크스페이스 이름<input id="workspaceName" name="name" required minlength="2" maxlength="40" placeholder="예: 재고 AX 파일럿"></label><label>워크스페이스 코드<input id="workspaceCode" name="code" required minlength="2" maxlength="24" placeholder="예: inventory-pilot"></label><label>연결 브랜드<select id="workspaceBrand" name="brandId"><option value="">브랜드 없음</option>${brands.map(brand=>`<option value="${escapeHtml(brand.id)}">${escapeHtml(brand.name)}</option>`).join('')}</select></label><label>시간대<select id="workspaceTimezone" name="timezone"><option value="Asia/Seoul">서울 (KST)</option><option value="Asia/Tokyo">도쿄 (JST)</option><option value="Asia/Shanghai">상하이 (CST)</option><option value="UTC">UTC</option></select></label><label class="workspace-test-check"><input id="workspaceIsTest" type="checkbox" checked><span><strong>테스트 데이터용</strong><small>왼쪽 바에 TEST 표시를 붙입니다.</small></span></label>${state.workspaceCreateError?`<p class="workspace-form-error">${escapeHtml(state.workspaceCreateError)}</p>`:''}<footer><button type="button" class="btn" id="workspaceCreateCancel">취소</button><button type="submit" class="btn primary" ${state.workspaceCreateBusy?'disabled':''}>${state.workspaceCreateBusy?'만드는 중…':'워크스페이스 만들기'}</button></footer></form></section></div>`}
function workspaceSettingsModal(){if(!state.workspaceSettingsOpen)return '';const workspace=currentBrandWorkspace(),brands=state.currentUser?.brands||[];return `<div class="workspace-modal-backdrop" id="workspaceSettingsBackdrop"><section class="workspace-modal workspace-settings-modal" role="dialog" aria-modal="true" aria-labelledby="workspaceSettingsTitle"><header><div><span>WORKSPACE SETTINGS</span><h2 id="workspaceSettingsTitle">워크스페이스 프로필 및 설정</h2><p>구성원이 쉽게 구분할 수 있는 기본 정보를 관리합니다.</p></div><button type="button" id="workspaceSettingsClose" aria-label="닫기">×</button></header><form id="workspaceSettingsForm"><label class="workspace-avatar-field">워크스페이스 이미지<div class="workspace-avatar-editor">${workspace.imageUrl?`<img id="workspaceAvatarPreview" src="${escapeHtml(workspace.imageUrl)}" alt="현재 워크스페이스 이미지">`:`<span id="workspaceAvatarPreview">${escapeHtml(workspace.code)}</span>`}<div><input id="workspaceImage" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG 또는 WebP · 최대 2MB</small></div></div></label><label>워크스페이스 이름<input id="workspaceSettingsName" required minlength="2" maxlength="40" value="${escapeHtml(workspace.name)}"></label><label>워크스페이스 코드<input id="workspaceSettingsCode" required minlength="2" maxlength="24" value="${escapeHtml(workspace.rawCode||workspace.code)}"></label><label class="workspace-description-field">설명<textarea id="workspaceDescription" maxlength="240" rows="3" placeholder="이 워크스페이스의 목적과 운영 범위를 설명해주세요.">${escapeHtml(workspace.description)}</textarea><small>최대 240자</small></label><label>연결 브랜드<select id="workspaceSettingsBrand"><option value="">브랜드 없음</option>${brands.map(brand=>`<option value="${escapeHtml(brand.id)}" ${String(brand.id)===String(workspace.brandId)?'selected':''}>${escapeHtml(brand.name)}</option>`).join('')}</select></label><label>시간대<select id="workspaceSettingsTimezone">${[['Asia/Seoul','서울 (KST)'],['Asia/Tokyo','도쿄 (JST)'],['Asia/Shanghai','상하이 (CST)'],['UTC','UTC']].map(([value,label])=>`<option value="${value}" ${value===workspace.timezone?'selected':''}>${label}</option>`).join('')}</select></label><label class="workspace-test-check"><input id="workspaceSettingsIsTest" type="checkbox" ${workspace.isTest?'checked':''}><span><strong>테스트 데이터용</strong><small>왼쪽 바에 TEST 표시를 붙입니다.</small></span></label>${state.workspaceSettingsError?`<p class="workspace-form-error">${escapeHtml(state.workspaceSettingsError)}</p>`:''}<footer><button type="button" class="btn" id="workspaceSettingsCancel">취소</button><button type="submit" class="btn primary" ${state.workspaceSettingsBusy?'disabled':''}>${state.workspaceSettingsBusy?'저장 중…':'변경사항 저장'}</button></footer></form></section></div>`}
function axPushShell(){const[title,sub]=pageMeta[state.page],connected=state.backendMode==='connected',workspace=currentBrandWorkspace();return `<div class="app workspace-enabled ${state.ai?'ax-panel-open':''}" data-workspace="${escapeHtml(workspace.id)}">${workspaceRail()}<aside class="sidebar ${state.menu?'open':''}"><div class="brand"><strong>VIIMsignal</strong><small>DECISION INTELLIGENCE</small></div><div class="sidebar-scroll">${allowedNav().map(([sec,items])=>`<div class="nav-section">${sec}</div><nav class="nav">${items.map(([id,label])=>`<button data-page="${id}" class="${id===state.page?'active':''}">${label}</button>`).join('')}</nav>`).join('')}</div><div class="sidebar-foot"><span class="sync">● ${connected?'DATA CONNECTED':'SAMPLE MODE'}</span><br>${escapeHtml(workspace.name)} 데이터 권한 적용</div></aside><main class="main"><header class="topbar"><div><button class="btn mobile-menu" id="menu" aria-label="메뉴 열기">☰</button><span class="breadcrumbs">${escapeHtml(organizationLabel())} / ${escapeHtml(workspace.name)} / ${title}</span></div><div class="top-actions">${axTopLauncher()}<select class="select hide-mobile" id="country" aria-label="국가 필터"><option>전체 국가</option><option>한국</option><option>중국</option><option>일본</option></select><select class="select hide-mobile" id="channel" aria-label="채널 필터"><option>전체 채널</option><option>자사몰</option><option>무신사</option><option>네이버</option><option>29CM</option><option>W컨셉</option><option>매장 POS</option></select><select class="select" id="role" aria-label="사용자 역할" disabled><option>대표</option><option>전체 관리자</option><option>팀 관리자</option><option>팀 구성원</option></select>${accountMenu()}<span class="live ${connected?'':'sample'}"><i class="dot"></i>${connected?'CONNECTED':'SAMPLE'}</span></div></header><section class="content"><div class="page-head"><div><span class="workspace-context">${escapeHtml(workspace.name)} 워크스페이스</span><h1>${title}</h1><p>${sub}</p></div></div><div class="dashboard-body">${renderPage()}</div></section></main>${axPushPanel()}${axApprovalModal()}${workspaceCreateModal()}${workspaceSettingsModal()}</div>`}
function axResultCard(){if(!state.aiResult||state.axMode==='detail')return '';const c=currentAxConfig();return `<section class="ax-result-card"><div class="ax-result-head"><div><small>${c.eyebrow}</small><h2>${c.title}</h2></div><span class="ax-fresh">${c.fresh}</span></div><div class="ax-metrics">${c.metrics.map(m=>`<div class="ax-metric ${m[3]||''}"><span>${m[0]}</span><strong>${m[1]}</strong><small>${m[2]}</small></div>`).join('')}</div><div class="ax-result-main"><div class="ax-viz"><div class="ax-panel-title"><div><h3>${c.chartTitle}</h3><p>${c.chartSub}</p></div><span>${state.page==='planning'?'기회 점수':state.page==='marketing'?'증분 효과':'실시간 분석'}</span></div>${axVisual(c)}</div><div class="ax-actions"><div class="ax-panel-title"><div><h3>AX가 찾은 실행 기회</h3><p>영향과 근거를 함께 검토합니다</p></div><span>${c.actions.length}개 액션</span></div><div class="ax-action-list">${c.actions.map((a,i)=>`<div class="ax-action-item"><span class="ax-action-index">0${i+1}</span><div><strong>${a[0]}</strong><small>${a[1]}</small></div><b>${a[2]}</b></div>`).join('')}</div><div class="ax-basis">판단 근거 · ${c.basis}</div></div></div>${state.axEvidence?`<div class="ax-evidence"><strong>근거 데이터</strong><br>${c.basis}. 마지막 동기화 23:59 KST, 현재 필터 ${state.country} · ${state.channel}. 모든 수치는 샘플데이터 기반입니다.</div>`:''}<footer class="ax-result-footer"><p>${c.note}</p><button class="ax-btn" data-ax-evidence>${state.axEvidence?'근거 닫기':'근거 데이터'}</button><button class="ax-btn outline" data-ax-detail>상세 분석</button><button class="ax-btn primary" data-ax-approve>${c.cta}</button></footer></section>`}
function axDetail(){if(!state.aiResult||state.axMode!=='detail')return '';const c=currentAxConfig();return `<section class="ax-detail-workspace"><div class="ax-detail-head"><div><h2>AX 분석 · ${c.chartTitle}</h2><p>질문에서 발견한 근거를 검증하고 실행안을 한 화면에서 승인합니다.</p></div><button class="ax-btn" data-ax-close-detail>빠른 결과로 돌아가기</button></div><div class="ax-metrics">${c.metrics.map(m=>`<div class="ax-metric ${m[3]||''}"><span>${m[0]}</span><strong>${m[1]}</strong><small>${m[2]}</small></div>`).join('')}</div><div class="ax-detail-grid"><div class="ax-viz"><div class="ax-panel-title"><div><h3>${c.chartTitle}</h3><p>${c.chartSub}</p></div><span>${c.fresh}</span></div>${axVisual(c)}</div><div class="ax-actions"><div class="ax-panel-title"><div><h3>핵심 판단</h3><p>${c.basis}</p></div></div><div class="ax-action-list">${c.actions.map((a,i)=>`<div class="ax-action-item"><span class="ax-action-index">0${i+1}</span><div><strong>${a[0]}</strong><small>${a[1]}</small></div><b>${a[2]}</b></div>`).join('')}</div></div><div class="card panel ax-detail-table"><div class="panel-title"><h3>추천 실행안과 근거 데이터</h3><span class="subtle">최근 업데이트 · 실시간 샘플</span></div><table class="table"><thead><tr><th>우선순위</th><th>실행 대상</th><th>근거</th><th>예상 효과</th><th>신뢰도</th><th>상태</th></tr></thead><tbody>${c.actions.map((a,i)=>`<tr><td>P${i}</td><td><strong>${a[0]}</strong></td><td>${a[1]}</td><td>${a[2]}</td><td>${94-i*4}%</td><td>${tag(i===0?'긴급':'검토',i===0?'danger':'')}</td></tr>`).join('')}</tbody></table></div></div><footer class="ax-result-footer"><p>${c.note}</p><button class="ax-btn outline" data-ax-evidence>근거 데이터</button><button class="ax-btn primary" data-ax-approve>${c.cta}</button></footer></section>`}
function axApprovalModal(){if(!state.axApproval)return '';const c=currentAxConfig(),a=c.approval||['현재 분석','실행 큐','승인'],selected=c.actions?.[state.axSelectedAction]||c.actions?.[0],executable=Boolean(selected?.[3]),title=executable?`${selected[0]}을(를) 승인할까요?`:`${c.cta}을(를) 승인할까요?`,current=executable?selected[1]:a[0],after=executable?(selected[3].action==='approve_transfer'?'재고 이동·배송 큐':'재주문·생산 실행 큐'):a[1];return `<div class="ax-modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="axApprovalTitle"><section class="ax-approval-modal"><header><span>승인 대기</span><small>신뢰도 94%</small></header><h2 id="axApprovalTitle">${escapeHtml(title)}</h2><p>${escapeHtml(c.note)}</p><div class="ax-approval-route"><div class="ax-route-node"><small>현재 상태</small><strong>${escapeHtml(current)}</strong></div><div class="ax-route-arrow">${escapeHtml(a[2])} →</div><div class="ax-route-node"><small>승인 후</small><strong>${escapeHtml(after)}</strong></div></div><div class="ax-impact-grid">${c.impact.map(x=>`<div><small>${escapeHtml(x[0])}</small><strong>${escapeHtml(x[1])}</strong></div>`).join('')}</div><div class="ax-basis">판단 근거 · ${escapeHtml(c.basis)}</div><div class="ax-modal-actions"><button class="ax-btn" data-ax-cancel>보류</button><button class="ax-btn outline" data-ax-review>담당자 검토</button><button class="ax-btn primary" data-ax-confirm>${executable?'승인 및 실행 큐 생성':'승인'}</button></div></section></div>`}
function axShell(){const[title,sub]=pageMeta[state.page];return `<div class="app"><aside class="sidebar ${state.menu?'open':''}"><div class="brand"><strong>VIIMsginal</strong><small>SELL-THROUGH OS</small></div><div class="sidebar-scroll">${allowedNav().map(([sec,items])=>`<div class="nav-section">${sec}</div><nav class="nav">${items.map(([id,l])=>`<button data-page="${id}" class="${id===state.page?'active':''}">${l}</button>`).join('')}</nav>`).join('')}</div><div class="sidebar-foot"><span class="sync">● DATA SYNC · LIVE</span><br>마지막 동기화 23:59 KST</div></aside><main class="main"><header class="topbar"><div><button class="btn mobile-menu" id="menu" aria-label="메뉴 열기">☰</button><span class="breadcrumbs">VIIMsginal / ${title}</span></div><div class="top-actions"><select class="select hide-mobile" id="country" aria-label="국가 필터"><option>전체 국가</option><option>한국</option><option>중국</option><option>일본</option></select><select class="select hide-mobile" id="channel" aria-label="채널 필터"><option>전체 채널</option><option>자사몰</option><option>무신사</option><option>네이버</option><option>29CM</option><option>W컨셉</option><option>매장 POS</option></select><select class="select" id="role" aria-label="사용자 역할" disabled><option>대표</option><option>전체 관리자</option><option>팀 관리자</option><option>팀 구성원</option></select>${accountMenu()}<span class="live"><i class="dot"></i>LIVE</span></div></header><section class="content"><div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div></div>${axCommand()}${axResultCard()}${axDetail()}<div class="dashboard-body ${state.aiResult?'ax-dimmed':''}">${renderPage()}</div></section></main><button id="ai" class="legacy-ax-stub" aria-hidden="true"></button><aside class="legacy-ax-stub"><button id="aiClose"></button></aside>${axApprovalModal()}</div>`}
function accountMenu(){const user=state.currentUser||{name:'사용자',team:'팀'},displayName=String(user.name||'사용자').replace(/^Fashion AX\b/i,'VIIMsignal');return `<div class="account-chip"><span>${displayName.slice(0,1)}</span><div><strong>${displayName}</strong><small>${user.team}</small></div></div><button class="logout-button" id="logout" type="button">로그아웃</button>`}
function loginPage(){const connected=state.backendMode==='connected';return `<main class="login-page"><section class="login-visual"><div class="login-brand"><strong>VIIMsignal</strong><small>DECIDE TODAY</small></div><div class="login-promise"><span>SIGNAL → DECIDE → ACT</span><h1>오늘의 신호를,<br>오늘의 결정으로.</h1><p>판매·재고·생산·마케팅 데이터를 연결해<br>지금 결정하고 실행해야 할 일을 제안합니다.</p></div><div class="login-signals"><div><small>지금 주목할 신호</small><strong>5건</strong><em>P0 2 · P1 2</em></div><div><small>보호 가능 매출</small><strong>₩42.0M</strong><em>3개 결정안</em></div><div><small>데이터 연결</small><strong>${connected?'SECURE':'DEMO'}</strong><em>${connected?'Supabase 연결':'샘플 데이터'}</em></div></div><footer>VICEVERSA · Fashion Decision Intelligence</footer></section><section class="login-panel"><div class="login-box"><div class="login-heading"><span>${connected?'SECURE WORKSPACE':'DEMO WORKSPACE'}</span><h2>VIIMsignal에 로그인</h2><p>회사 계정으로 오늘의 결정과 팀 실행 현황을 확인하세요.</p></div><form id="loginForm" class="login-form"><label>이메일<input id="loginEmail" name="email" type="email" autocomplete="username" placeholder="name@company.com" required></label><label>비밀번호<input id="loginPassword" name="password" type="password" autocomplete="current-password" placeholder="비밀번호 입력" required></label>${state.loginError?`<div class="login-error" role="alert">${state.loginError}</div>`:''}<button class="login-submit" type="submit">${connected?'회사 계정으로 로그인':'로그인'}</button></form>${connected?'':`<div class="login-divider"><span>DEMO ACCESS</span></div><div class="demo-accounts"><button type="button" data-demo-account="ceo@fashionax.demo"><span>대표</span><strong>김대표 계정</strong><small>전사 데이터·승인</small></button><button type="button" data-demo-account="inventory@fashionax.demo"><span>재고</span><strong>재고운영 계정</strong><small>재고·물류 범위</small></button></div><div class="demo-credential"><span>데모 비밀번호</span><code>demo1234</code></div>`}<p class="login-notice">${connected?'서버 인증과 회사별 데이터 권한이 적용됩니다.':'Supabase 환경변수가 없는 개발 환경에서는 데모 인증으로 동작합니다.'}</p></div></section></main>`}
function passwordSetupPage(){const label=state.authLink?.type==='recovery'?'새 비밀번호 설정':'초대 계정 활성화';return `<main class="login-page"><section class="login-visual"><div class="login-brand"><strong>VIIMsignal</strong><small>DECIDE TODAY</small></div><div class="login-promise"><span>SIGNAL → DECIDE → ACT</span><h1>팀의 신호를,<br>오늘의 결정으로.</h1><p>비밀번호를 설정하면 회사 데이터와<br>허용된 팀의 의사결정 워크스페이스에 연결됩니다.</p></div><footer>VICEVERSA · Fashion Decision Intelligence</footer></section><section class="login-panel"><div class="login-box"><div class="login-heading"><span>ACCOUNT SETUP</span><h2>${label}</h2><p>앞으로 VIIMsignal 로그인에 사용할 비밀번호를 입력하세요.</p></div><form id="passwordSetupForm" class="login-form"><label>새 비밀번호<input id="newPassword" type="password" autocomplete="new-password" minlength="8" placeholder="8자 이상" required></label><label>비밀번호 확인<input id="confirmPassword" type="password" autocomplete="new-password" minlength="8" placeholder="한 번 더 입력" required></label>${state.loginError?`<div class="login-error" role="alert">${state.loginError}</div>`:''}<button class="login-submit" type="submit">비밀번호 설정하고 시작</button></form><p class="login-notice">이 링크는 계정 보안을 위해 한 번만 사용할 수 있습니다.</p></div></section></main>`}
const configFromAxResponseBase=configFromAxResponse;
configFromAxResponse=function(payload){const rows=payload.visualization?.rows||[],metric=payload.plan?.metric;if(metric!=='discount')return configFromAxResponseBase(payload);const base=axConfigs.profitability||axFallback();if(!rows.length)return {...base,fresh:'추천 스냅샷 없음',title:'현재 조건에서 생성된 할인 추천이 없습니다',note:payload.warning||'관리자가 할인 추천 스냅샷을 먼저 계산해야 합니다.'};const uplift=rows.reduce((sum,row)=>sum+Math.max(0,Number(row.contribution_uplift||0)),0),hold=rows.filter(row=>Number(row.recommended_discount_rate||0)<=5),avgConfidence=rows.reduce((sum,row)=>sum+Number(row.confidence||0),0)/rows.length,max=Math.max(...rows.map(row=>Number(row.expected_contribution_margin||0)),1),top=[...rows].sort((a,b)=>Number(b.contribution_uplift||0)-Number(a.contribution_uplift||0));return {...base,eyebrow:'AX 최적 할인 분석',title:'상품·채널별 최적 할인값과 비할인 대안을 찾았습니다',fresh:'추천 스냅샷 · API 재계산 없음',metrics:[['예상 기여이익 개선',discountMoney(uplift),'14일 기준'],['정상가·저할인 권장',`${hold.length}건`,'0–5%'],['검토 조합',`${rows.length}건`,'상품 × 채널'],['평균 신뢰도',`${Math.round(avgConfidence*100)}%`,'과거 가격 이력']],visual:'bars',chartTitle:'상품·채널별 권장 할인율',chartSub:'기여이익 − 잔여재고 위험비용이 최대인 구간',rows:top.slice(0,12).map(row=>[`${row.product_code} · ${row.channel_code}`,Math.max(5,Math.round(Number(row.expected_contribution_margin||0)/max*100)),`현재 ${Number(row.current_discount_rate||0).toFixed(0)}% → 권장 ${Number(row.recommended_discount_rate||0).toFixed(0)}%`,Number(row.recommended_discount_rate||0)>=20?'watch':'']),actions:top.slice(0,3).map(row=>[`${row.product_code} ${discountTypeLabel(row.recommendation_type)}`,`${row.channel_code} · ${row.non_discount_action||'선별 적용'}`,`${Number(row.recommended_discount_rate||0).toFixed(0)}%`]),basis:'가격 탄력성 + 상품 원가 + 채널비 + 재고커버 + 잔여재고 위험',note:'원천 주문을 다시 AI에 보내지 않고 저장된 6개 할인 시나리오의 최적값을 조회했습니다.',cta:'할인안 검토',approval:[`${rows.length}개 추천안`,'가격 운영 승인 큐','검토 완료'],impact:[['기여이익 개선',discountMoney(uplift)],['저할인 권장',`${hold.length}건`],['평균 신뢰도',`${Math.round(avgConfidence*100)}%`]]}}
function recordPerformance(type,name,started,meta={}){const durationMs=Math.round(performance.now()-started),entry={type,name,durationMs,page:state.page,status:meta.status??null,at:new Date().toISOString()};try{const existing=JSON.parse(sessionStorage.getItem('viimsignalPerformance')||'[]'),next=[...existing,entry].slice(-150);sessionStorage.setItem('viimsignalPerformance',JSON.stringify(next));window.__VIIMSIGNAL_PERFORMANCE__=next}catch{}if(durationMs>=800)console.warn(`[VIIMsignal performance] ${JSON.stringify(entry)}`);return durationMs}
const pendingApiRequests=new Map();
async function apiRequestDirect(path,options={},retried=false){const started=performance.now(),workspace=currentBrandWorkspace(),scopeHeaders=workspace?.source==='workspace'?{'x-viimsignal-workspace-id':workspace.id,...(workspace.brandId?{'x-viimsignal-brand-id':workspace.brandId}:{})}:workspace?.source==='backend'?{'x-viimsignal-brand-id':workspace.id}:{},method=options.method||'GET',metricName=`${method} ${String(path).split('&')[0]}`;let status=null;try{const response=await fetch(path,{credentials:'include',...options,headers:{...(options.body instanceof FormData?{}:{'content-type':'application/json'}),...scopeHeaders,...(options.headers||{})}});status=response.status;const type=response.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error('API_UNAVAILABLE');const payload=await response.json();if(response.status===401&&!retried&&path!=='/api/auth/session'&&path!=='/api/auth/login'){const session=await apiRequestDirect('/api/auth/session',{},true);if(session.authenticated)return apiRequestDirect(path,options,true)}if(!response.ok){const error=new Error(payload.error||`API ${response.status}`);error.status=response.status;error.code=payload.code;throw error}return payload}finally{recordPerformance('api',metricName,started,{status})}}
async function apiRequest(path,options={},retried=false){const method=String(options.method||'GET').toUpperCase();if(method!=='GET'||retried)return apiRequestDirect(path,options,retried);const workspace=currentBrandWorkspace(),key=`${workspace?.id||'none'}:${path}`;if(pendingApiRequests.has(key))return pendingApiRequests.get(key);const request=apiRequestDirect(path,options,retried).finally(()=>pendingApiRequests.delete(key));pendingApiRequests.set(key,request);return request}
async function axStreamRequest(body,onEvent=()=>{}){const started=performance.now(),workspace=currentBrandWorkspace(),scopeHeaders=workspace?.source==='workspace'?{'x-viimsignal-workspace-id':workspace.id,...(workspace.brandId?{'x-viimsignal-brand-id':workspace.brandId}:{})}:workspace?.source==='backend'?{'x-viimsignal-brand-id':workspace.id}:{},response=await fetch('/api/ax/stream',{method:'POST',credentials:'include',headers:{'content-type':'application/json',...scopeHeaders},body:JSON.stringify(body)});let payload=null,buffer='',streamError=null;try{const type=response.headers.get('content-type')||'';if(!type.includes('application/x-ndjson'))throw new Error('API_UNAVAILABLE');const reader=response.body?.getReader(),decoder=new TextDecoder();if(!reader)throw new Error('STREAM_UNAVAILABLE');while(true){const{done,value}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines){if(!line.trim())continue;const event=JSON.parse(line);onEvent(event);if(event.type==='complete')payload=event.payload;if(event.type==='error')streamError=Object.assign(new Error(event.error||'AX 분석 요청에 실패했습니다.'),{status:event.status})}if(done)break}if(buffer.trim()){const event=JSON.parse(buffer);onEvent(event);if(event.type==='complete')payload=event.payload;if(event.type==='error')streamError=Object.assign(new Error(event.error||'AX 분석 요청에 실패했습니다.'),{status:event.status})}if(streamError)throw streamError;if(!response.ok)throw new Error(`AX ${response.status}`);if(!payload)throw new Error('AX 응답이 완료되지 않았습니다.');return payload}finally{recordPerformance('api','POST /api/ax/stream',started,{status:response.status})}}
