async function createWorkspace(){if(state.workspaceCreateBusy)return;const name=document.querySelector('#workspaceName')?.value||'',code=document.querySelector('#workspaceCode')?.value||'',brandId=document.querySelector('#workspaceBrand')?.value||null,timezone=document.querySelector('#workspaceTimezone')?.value||'Asia/Seoul',isTest=Boolean(document.querySelector('#workspaceIsTest')?.checked);state.workspaceCreateBusy=true;state.workspaceCreateError='';render();try{const result=await apiRequest('/api/auth/workspaces',{method:'POST',body:JSON.stringify({name,code,brandId,timezone,isTest})}),session=await apiRequest('/api/auth/session');state.currentUser=normalizeBackendUser(session.user);sessionStorage.setItem('fashionAxSession',JSON.stringify(state.currentUser));saveBrandWorkspace(result.workspace.id);resetBrandScopedState();state.workspaceCreateOpen=false;toast(`${result.workspace.name} 워크스페이스를 만들었습니다.`)}catch(error){state.workspaceCreateError=error.message||'워크스페이스를 만들지 못했습니다.'}finally{state.workspaceCreateBusy=false;render()}}
