async function saveWorkspaceSettings(){if(state.workspaceSettingsBusy)return;const workspace=currentBrandWorkspace(),image=document.querySelector('#workspaceImage')?.files?.[0];if(image&&image.size>2*1024*1024){state.workspaceSettingsError='이미지는 2MB 이하로 선택해주세요.';render();return}const payload={workspaceId:workspace.id,name:document.querySelector('#workspaceSettingsName')?.value||'',code:document.querySelector('#workspaceSettingsCode')?.value||'',description:document.querySelector('#workspaceDescription')?.value||'',brandId:document.querySelector('#workspaceSettingsBrand')?.value||null,timezone:document.querySelector('#workspaceSettingsTimezone')?.value||'Asia/Seoul',isTest:Boolean(document.querySelector('#workspaceSettingsIsTest')?.checked)},form=new FormData();form.append('payload',JSON.stringify(payload));if(image)form.append('image',image);state.workspaceSettingsBusy=true;state.workspaceSettingsError='';render();try{await apiRequest('/api/auth/workspaces',{method:'PATCH',body:form}),session=await apiRequest('/api/auth/session');state.currentUser=normalizeBackendUser(session.user);sessionStorage.setItem('fashionAxSession',JSON.stringify(state.currentUser));state.workspaceSettingsOpen=false;state.workspaceMenuOpen=false;toast('워크스페이스 설정을 저장했습니다.')}catch(error){state.workspaceSettingsError=error.message||'워크스페이스 설정을 저장하지 못했습니다.'}finally{state.workspaceSettingsBusy=false;render()}}
