 const mappingRows=specs.map(([field,label,required])=>{const selected=p.mapping?.[field]||'';return `<label class="mapping-field-row"><span><strong>${escapeHtml(label)}</strong><small>${escapeHtml(field)} ${required?'<b>필수</b>':'선택'}</small></span><select data-upload-map="${escapeHtml(field)}"><option value="">연결하지 않음</option>${(p.headers||[]).map(header=>`<option value="${escapeHtml(header)}" ${header===selected?'selected':''}>${escapeHtml(header)}</option>`).join('')}</select></label>`}).join('');
 const entityLabel=importEntityLabel(p.entityType),resultPage=p.entityType==='sales_order'?'hub':p.entityType==='inventory_snapshot'?'inventory':p.entityType==='product_review'?'customers':'planning';
 return `<div class="card panel upload-preview-panel"><div class="panel-title"><div><h2>${entityLabel} 파일 실제 미리보기</h2><span class="subtle">${escapeHtml(p.filename)} · ${p.totalRows.toLocaleString()}행 · ${period}</span></div>${tag(imported?.status==='completed'?'적재 완료':p.missingFields.length?'매핑 필요':p.errorRows?'일부 오류':'적재 가능',p.missingFields.length||p.errorRows?'warning':'')}</div>${detectionPanel}<div class="upload-preview-kpis"><div><small>정상 행</small><strong>${p.validRows.toLocaleString()}</strong></div><div><small>오류 행</small><strong>${p.errorRows.toLocaleString()}</strong></div><div><small>인식 컬럼</small><strong>${Object.keys(p.mapping||{}).length}</strong></div><div><small>필수 매핑 누락</small><strong>${p.missingFields.length}</strong></div></div><section class="mapping-editor"><div class="mapping-editor-head"><div><strong>회사별 컬럼 매핑</strong><span>처음 한 번 확인하고 저장하면 같은 컬럼 형식에 자동 적용됩니다.</span></div>${tag(mappingStatus,mappingTone)}</div><div class="mapping-field-grid">${mappingRows}</div><div class="mapping-editor-actions"><button class="btn" id="applyUploadMapping" ${state.uploadBusy||!state.uploadMappingDirty?'disabled':''}>변경 매핑 다시 검증</button><button class="btn primary" id="saveUploadMapping" ${state.uploadMappingBusy||state.uploadMappingDirty||p.missingFields.length?'disabled':''}>${state.uploadMappingBusy?'저장 중…':p.mappingSource==='saved_template'?'회사 매핑 업데이트':'이 회사 형식으로 저장'}</button></div></section>${p.sample?.length?`<div class="actual-preview-table"><strong>원본에서 읽은 정상 데이터</strong><div class="preview-scroll"><table class="table"><thead><tr>${Object.keys(p.sample[0]).filter(key=>!['raw_row'].includes(key)).slice(0,8).map(key=>`<th>${escapeHtml(key)}</th>`).join('')}</tr></thead><tbody>${p.sample.slice(0,5).map(row=>`<tr>${Object.keys(p.sample[0]).filter(key=>!['raw_row'].includes(key)).slice(0,8).map(key=>`<td>${escapeHtml(row[key]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`:''}${p.errors.length?`<div class="upload-error-list"><strong>우선 확인할 오류 · 오류 행은 정상 행과 분리됩니다.</strong>${p.errors.slice(0,5).map(e=>`<span>${e.row_number}행 · ${escapeHtml(e.message)}</span>`).join('')}</div>`:''}<div class="upload-preview-actions"><button class="btn" id="clearUploadPreview">다른 파일 선택</button>${imported?`<button class="btn primary" data-page="${resultPage}">반영 결과 확인</button>`:`<button class="btn primary" id="importDataFile" ${p.missingFields.length||state.uploadBusy||state.uploadMappingDirty?'disabled':''}>${entityLabel} 적재</button>`}</div></div>`
