function importEntityLabel(type){return type==='product_master'?'상품·SKU 마스터':type==='sales_order'?'판매 주문':type==='inventory_snapshot'?'재고 스냅샷':type==='product_review'?'리뷰·VOC':type||'데이터'}
function importStatusMeta(status){return status==='completed'?['완료','']:status==='partial'?['일부 오류','warning']:status==='failed'?['실패','danger']:status==='processing'?['처리 중','warning']:['대기','']}
function analyticsStatusMeta(analytics){if(!analytics)return ['분석 기록 없음',''];if(analytics.status==='completed')return ['대시보드·추천 갱신 완료',''];if(analytics.status==='partial')return ['일부 분석 확인 필요','warning'];if(analytics.status==='blocked')return ['정합성 불일치 · 갱신 차단','danger'];if(analytics.status==='failed')return ['분석 갱신 실패','danger'];return ['분석 생략','']}
function importHistoryPanel(){
 if(state.backendMode!=='connected')return '';
 const payload=state.importHistory||{},jobs=payload.jobs||[],latest=jobs[0],selected=jobs.find(job=>job.id===state.selectedImportJob)||latest,runs=payload.analyticsRuns||[],completedRuns=runs.filter(run=>run.status==='completed').length,lastRefresh=runs.find(run=>run.status==='completed')?.completed_at,historyBody=state.importHistoryLoading&&!state.importHistory?'<div class="operational-loading">최근 적재와 분석 상태를 불러오는 중입니다.</div>':jobs.length?jobs.slice(0,25).map(job=>{const[statusLabel,statusTone]=importStatusMeta(job.status),[analysisLabel,analysisTone]=analyticsStatusMeta(job.summary?.analytics);return `<button class="import-history-row ${selected?.id===job.id?'active':''}" data-import-job="${job.id}"><span>${tag(statusLabel,statusTone)}</span><div><strong>${escapeHtml(job.filename)}</strong><small>${importEntityLabel(job.entity_type)} · ${job.completed_at?new Date(job.completed_at).toLocaleString('ko-KR'):'처리 중'}</small></div><b>${Number(job.success_rows||0).toLocaleString()} / ${Number(job.total_rows||0).toLocaleString()}행<small>오류 ${Number(job.error_rows||0).toLocaleString()}</small></b><em class="${analysisTone}">${analysisLabel}</em><i aria-hidden="true">›</i></button>`}).join(''):'<div class="operational-empty compact"><strong>아직 적재 이력이 없습니다.</strong><p>판매 또는 재고 파일을 적재하면 처리 결과와 자동 분석 상태가 여기에 표시됩니다.</p></div>',selectedAnalytics=selected?.summary?.analytics,[selectedAnalysisLabel,selectedAnalysisTone]=analyticsStatusMeta(selectedAnalytics);
 return `<section class="card panel import-operations"><div class="panel-title"><div><h2>적재·자동 분석 이력</h2><span class="subtle">파일 적재 → 지표 반영 → 수요예측·할인 추천 → 오늘의 액션 갱신</span></div><button class="btn" id="reloadImports" ${state.importHistoryLoading?'disabled':''}>${state.importHistoryLoading?'확인 중…':'새로고침'}</button></div><div class="import-pipeline-strip"><div><span>최근 적재</span><strong>${latest?new Date(latest.completed_at||latest.created_at).toLocaleString('ko-KR'):'없음'}</strong></div><div><span>최근 분석 반영</span><strong>${lastRefresh?new Date(lastRefresh).toLocaleString('ko-KR'):'없음'}</strong></div><div><span>최근 분석 성공</span><strong>${completedRuns}/${runs.length||0}회</strong></div><div><span>운영 방식</span><strong>적재 후 자동 갱신</strong></div></div><div class="import-history-layout"><div class="import-history-list">${historyBody}</div>${selected?`<aside class="import-job-detail"><header><div><small>${importEntityLabel(selected.entity_type)}</small><h3>${escapeHtml(selected.filename)}</h3></div>${tag(importStatusMeta(selected.status)[0],importStatusMeta(selected.status)[1])}</header><dl><div><dt>전체 행</dt><dd>${Number(selected.total_rows||0).toLocaleString()}</dd></div><div><dt>정상 행</dt><dd>${Number(selected.success_rows||0).toLocaleString()}</dd></div><div><dt>신규 / 갱신</dt><dd>${Number(selected.inserted_rows||0).toLocaleString()} / ${Number(selected.updated_rows||0).toLocaleString()}</dd></div><div><dt>오류 행</dt><dd>${Number(selected.error_rows||0).toLocaleString()}</dd></div></dl><div class="import-analysis-status ${selectedAnalysisTone}"><strong>${selectedAnalysisLabel}</strong><span>기준일 ${selectedAnalytics?.asOfDate||selected.summary?.period?.end?.slice?.(0,10)||'확인 필요'}</span>${(selectedAnalytics?.results||[]).map(result=>`<p><b>${escapeHtml(result.label)}</b><em>${result.status==='completed'?'완료':escapeHtml(result.error||'실패')}</em></p>`).join('')}</div>${selected.errors?.length?`<div class="import-error-preview"><strong>우선 확인할 오류</strong>${selected.errors.slice(0,3).map(error=>`<p>${Number(error.row_number||0).toLocaleString()}행 · ${escapeHtml(error.message)}</p>`).join('')}</div>`:''}<footer><button class="btn" data-page="${selected.entity_type==='sales_order'?'hub':'inventory'}">반영 화면 보기</button>${Number(selected.error_rows||0)>0?`<button class="btn" data-download-import-errors="${selected.id}" data-import-filename="${escapeHtml(selected.filename)}">오류 CSV 다운로드</button>`:''}</footer></aside>`:''}</div></section>`
}
