function validUploadFile(file){if(!/\.(csv|xlsx)$/i.test(file.name))return 'CSV 또는 XLSX 파일만 올릴 수 있습니다.';if(file.size>20*1024*1024)return '파일은 최대 20MB까지 올릴 수 있습니다.';return ''}
