async function loadProductionWorkflows(force=false){if(state.backendMode!=='connected'||state.page!=='production'||(state.productionWorkflowData&&!force)||state.productionWorkflowLoading)return;state.productionWorkflowLoading=true;state.productionWorkflowError='';try{state.productionWorkflowData=await apiRequest('/api/dashboards/query?resource=production-workflows')}catch(error){state.productionWorkflowError=error.message||'생산 실행 큐를 불러오지 못했습니다.';console.warn('[Production workflow]',state.productionWorkflowError)}finally{state.productionWorkflowLoading=false;refreshDashboardBody({expectedPage:'production'})}}
