async function loadTodayActions(force=false){if(state.backendMode!=='connected'||state.page!=='action'||(state.todayActionsData&&!force)||state.todayActionsLoading)return;state.todayActionsLoading=true;state.todayActionsError='';try{state.todayActionsData=await apiRequest('/api/dashboards/query?resource=decision-actions')}catch(error){state.todayActionsError=error.message||'오늘의 의사결정 안건을 불러오지 못했습니다.';console.warn('[Today actions]',state.todayActionsError)}finally{state.todayActionsLoading=false;refreshDashboardBody({expectedPage:'action'})}}
async function loadDecisionWorkflow(force=false){if(state.backendMode!=='connected'||!['decisions','execution'].includes(state.page)||(state.decisionWorkflowData&&!force)||state.decisionWorkflowLoading)return;state.decisionWorkflowLoading=true;state.decisionWorkflowError='';try{state.decisionWorkflowData=await apiRequest(`/api/decisions/workflow?page=${state.page}`)}catch(error){state.decisionWorkflowError=error.message||'결정·실행 데이터를 불러오지 못했습니다.';console.warn('[Decision workflow]',state.decisionWorkflowError)}finally{state.decisionWorkflowLoading=false;refreshDashboardBody({expectedPage:state.page})}}
async function submitRecommendationDecision(lineId,decision){if(state.decisionWorkflowBusy)return;const quantity=Number(document.querySelector('#decisionQuantity')?.value||0),reasonCode=document.querySelector('#decisionReason')?.value||'',note=document.querySelector('#decisionNote')?.value||'',requestedExecutionDate=document.querySelector('#decisionExecutionDate')?.value||null;state.decisionWorkflowBusy=true;refreshDashboardBody({expectedPage:'decisions'});try{const result=await apiRequest('/api/decisions/workflow',{method:'POST',body:JSON.stringify({action:'decide',recommendationLineId:lineId,decision,quantity,reasonCode,note,requestedExecutionDate})});state.decisionWorkflowData=null;await loadDecisionWorkflow(true);toast(result.execution?`결정을 저장하고 실행 요청 ${result.execution.execution_no}을 생성했습니다.`:'결정을 저장했습니다.')}catch(error){toast(`결정 저장 실패 · ${error.message}`)}finally{state.decisionWorkflowBusy=false;refreshDashboardBody({expectedPage:'decisions'})}}
