async function reviewPolicyCandidate(candidateId,decision){if(state.decisionWorkflowBusy)return;state.decisionWorkflowBusy=true;try{await apiRequest('/api/decisions/workflow',{method:'POST',body:JSON.stringify({action:'review_policy',candidateId,decision})});state.decisionWorkflowData=null;await loadDecisionWorkflow(true);toast(decision==='apply'?'학습 정책을 다음 추천에 적용합니다.':decision==='approve'?'학습 정책을 승인했습니다.':'학습 정책을 거절했습니다.')}catch(error){toast(`정책 처리 실패 · ${error.message}`)}finally{state.decisionWorkflowBusy=false;refreshDashboardBody({expectedPage:'decisions'})}}
function renderLearningPolicyPanel(){const data=state.decisionWorkflowData,workspace=document.querySelector('.decision-workspace'),candidates=(data?.policyCandidates||[]).filter(item=>['proposed','approved','applied'].includes(item.status));if(!workspace||!candidates.length)return;const latestDate=(data.forecasts||[]).map(row=>row.as_of_date).sort().at(-1),forecasts=(data.forecasts||[]).filter(row=>row.as_of_date===latestDate),panel=document.createElement('section');panel.className='card panel learning-policy-panel';panel.innerHTML=`<div class="panel-title"><div><h2>성과 학습 정책</h2><p class="subtle">D+28 검증 결과 3건 이상 · 적용 전 예상 수요 변화를 비교하고 필요하면 즉시 롤백합니다.</p></div></div><div class="learning-policy-list">${candidates.map(item=>{const sku=(data.skus||[]).find(row=>String(row.id)===String(item.sku_id)),location=(data.locations||[]).find(row=>String(row.id)===String(item.location_id)),base=forecasts.filter(row=>String(row.sku_id)===String(item.sku_id)&&String(row.location_id)===String(item.location_id)).reduce((sum,row)=>sum+Number(row.p50_qty||0),0),multiplier=Number(item.proposed_value?.multiplier||1),projected=base*multiplier,delta=projected-base;return `<article><div><strong>${escapeHtml(sku?.sku_code||'SKU')} · ${escapeHtml(location?.location_name||'위치')}</strong><span>현재 예측 ${Math.round(base).toLocaleString()} → 적용 시 ${Math.round(projected).toLocaleString()} pcs (${delta>=0?'+':''}${Math.round(delta).toLocaleString()})</span><small>보정 ×${multiplier.toFixed(2)} · 근거 ${Number(item.evidence_count||0)}건 · 신뢰도 ${Math.round(Number(item.confidence||0)*100)}% · 양의 성과 ${Math.round(Number(item.expected_improvement?.positive_outcome_share||0)*100)}%</small></div><div>${item.status==='proposed'?`<button class="btn" data-policy-decision="reject" data-policy-id="${item.id}">거절</button><button class="btn primary" data-policy-decision="approve" data-policy-id="${item.id}">승인</button>`:item.status==='approved'?`<button class="btn primary" data-policy-decision="apply" data-policy-id="${item.id}">적용</button>`:`<span class="tag">적용 중</span><button class="btn" data-policy-decision="rollback" data-policy-id="${item.id}">롤백</button>`}</div></article>`}).join('')}</div>`;workspace.insertAdjacentElement('afterend',panel)}
function renderDecisionOperationsPanel(){if(state.currentPage!=='execution'||!state.decisionWorkflowData)return;const data=state.decisionWorkflowData,grid=document.querySelector('.execution-grid');if(!grid)return;const decisions=(data.decisions||[]).filter(row=>row.is_current),accepted=decisions.filter(row=>['approved','adjusted'].includes(row.decision)),executions=data.executions||[],completed=executions.filter(row=>row.status==='completed'),outcomes=(data.outcomes||[]).filter(row=>row.outcome_status==='complete'),positive=outcomes.filter(row=>Number(row.realized_net_value||0)>0),policies=(data.policyCandidates||[]).filter(row=>row.status==='applied'),percent=(value,total)=>total?`${Math.round(value/total*100)}%`:'—',panel=document.createElement('section');panel.className='card panel';panel.innerHTML=`<div class="panel-title"><div><h2>의사결정 운영 지표</h2><p class="subtle">추천부터 실행·성과·학습 정책까지의 폐쇄 루프 상태</p></div></div>${kpi([['추천 채택률',percent(accepted.length,decisions.length),`${accepted.length}/${decisions.length}건`],['수정 승인률',percent(decisions.filter(row=>row.decision==='adjusted').length,accepted.length),'현장 판단 반영'],['실행 완료율',percent(completed.length,executions.length),`${completed.length}/${executions.length}건`],['양의 성과율',percent(positive.length,outcomes.length),`적용 정책 ${policies.length}건`]])}`;grid.insertAdjacentElement('afterend',panel)}
async function reviewTodayAction(actionKey,decision,title=''){if(state.todayActionBusy)return;if(decision==='approved'&&!canApprovePage('action')){toast('이 계정에는 안건 승인 권한이 없습니다.');return}if(state.backendMode!=='connected'){const index=Number(String(actionKey).replace('demo:',''))||0;state.todayActionStatuses[index]=decision;refreshDashboardBody({expectedPage:'action'});toast(`${todayActions[index]?.title||title} 안건을 ${decision==='approved'?'승인':'보류'}했습니다.`);return}state.todayActionBusy=actionKey;refreshDashboardBody({expectedPage:'action'});try{const result=await apiRequest('/api/dashboards/query?resource=decision-actions',{method:'POST',body:JSON.stringify({actionKey,decision})});state.todaySelectedKey=actionKey;state.todayActionsData=null;state.inventoryWorkflowData=null;state.productionWorkflowData=null;state.discountIntelligence=null;await loadTodayActions(true);const labels={approved:'승인되어 실제 업무 큐에 전달되었습니다.',held:'보류 상태로 저장했습니다.',adjustment_requested:'조건 조정 요청을 저장했습니다.'};toast(labels[decision]||'결정 상태를 저장했습니다.');return result}catch(error){toast(`안건 처리 실패 · ${error.message}`);throw error}finally{state.todayActionBusy='';refreshDashboardBody({expectedPage:'action'})}}
