function customerLiveDashboard(){const data=state.customerDbData;if(state.customerDbLoading&&!data)return '<div class="card panel operational-loading">익명 고객과 배송지역을 집계하고 있습니다.</div>';if(state.customerDbError&&!data)return `<div class="data-provenance stale"><strong>고객 데이터 조회 실패</strong><span>${escapeHtml(state.customerDbError)}</span></div>${customersDashboardSample()}`;if(!data?.hasData)return `<div class="data-provenance sample"><strong>고객 데이터 없음</strong><span>익명 고객 ID와 배송지역이 포함된 판매 파일을 적재하면 실제 데이터로 전환됩니다.</span></div>${customersDashboardSample()}`;const s=data.summary||{},regions=data.regions||[],segments=data.segments||{},formatMoney=value=>`₩${Math.round(Number(value||0)/1000).toLocaleString()}K`,maxRegion=Math.max(...regions.map(row=>Number(row.net_sales||0)),1);return `<div class="data-provenance connected"><strong>SUPABASE LIVE · PRIVACY SAFE</strong><span>최근 ${data.periodDays}일 · 익명 고객 토큰과 시군구 단위 배송지역만 사용</span><button class="btn" id="refreshCustomerInsights">새로고침</button></div>${kpi([['익명 고객',`${Number(s.anonymousCustomers||0).toLocaleString()}명`,`식별률 ${Number(data.profileCoverage?.customerTokenPct||0).toFixed(1)}%`],['재구매 고객',`${Number(s.repeatCustomerPct||0).toFixed(1)}%`,`${Number(s.repeatCustomers||0).toLocaleString()}명`],['평균 구매주기',s.averagePurchaseCycleDays==null?'확인 중':`${Number(s.averagePurchaseCycleDays).toFixed(1)}일`,'구매 2회 이상'],['평균 객단가',formatMoney(s.averageOrderValue),`${Number(s.orders||0).toLocaleString()}건`]])}<div class="grid split"><section class="card panel"><div class="panel-title"><div><h2>실제 주문 배송지역</h2><span class="subtle">상세주소 제외 · 시군구 집계</span></div>${tag('LIVE')}</div><table class="table"><thead><tr><th>지역</th><th>주문</th><th>매출·구성</th><th>객단가</th><th>재구매 주문</th></tr></thead><tbody>${regions.slice(0,12).map(row=>`<tr><td><strong>${escapeHtml(row.label)}</strong></td><td>${Number(row.orders).toLocaleString()}건</td><td>${formatMoney(row.net_sales)} <span class="percent-chip">${Number(row.sales_share_pct).toFixed(1)}%</span></td><td>${formatMoney(row.average_order_value)}</td><td>${Number(row.repeat_order_pct).toFixed(1)}%</td></tr>`).join('')}</tbody></table></section><section class="card panel"><h2>권역별 수요 집중도</h2>${bars(regions.slice(0,8).map(row=>[escapeHtml(row.label),`${Number(row.orders).toLocaleString()} orders`,Math.max(4,Number(row.net_sales||0)/maxRegion*100)]))}<div class="customer-callout"><strong>배송지역 입력률 ${Number(data.profileCoverage?.shippingRegionPct||0).toFixed(1)}%</strong><span>성별·연령은 연결되지 않았으며 추정값을 표시하지 않습니다.</span></div></section></div><div class="grid split"><section class="card panel"><h2>실제 구매 횟수 세그먼트</h2><div class="segment-grid">${[['VIP',segments.vip||0,'6회+'],['충성',segments.loyal||0,'4–5회'],['성장',segments.growth||0,'2–3회'],['신규',segments.new||0,'1회']].map((row,i)=>`<div class="segment s${i}"><span>${row[0]}</span><strong>${Number(row[1]).toLocaleString()}명</strong><small>구매 ${row[2]}</small></div>`).join('')}</div></section><section class="card panel"><h2>데이터 품질</h2><div class="ai-list"><div><strong>익명 고객 식별률</strong><span>${Number(data.profileCoverage?.customerTokenPct||0).toFixed(1)}% · 직접 식별정보 미사용</span></div><div><strong>배송지역 입력률</strong><span>${Number(data.profileCoverage?.shippingRegionPct||0).toFixed(1)}% · 시군구까지만 집계</span></div><button data-query="재구매 고객과 지역별 수요의 차이를 분석해줘">VIIM AX로 고객 신호 분석</button></div></section></div>`}
function returnsLiveDashboard(){const data=state.returnsDbData;if(state.returnsDbLoading&&!data)return '<div class="card panel operational-loading">실제 반품·취소 수량과 손실을 집계하고 있습니다.</div>';if(state.returnsDbError&&!data)return `<div class="data-provenance stale"><strong>반품 데이터 조회 실패</strong><span>${escapeHtml(state.returnsDbError)}</span></div>${returnsDashboardSample()}`;if(!data?.hasData)return `<div class="data-provenance sample"><strong>반품 데이터 없음</strong><span>반품 수량과 주문 상태가 포함된 판매 파일을 적재하면 실제 데이터로 전환됩니다.</span></div>${returnsDashboardSample()}`;const s=data.summary||{},channels=data.channels||[],products=data.products||[],moneyM=value=>`₩${(Number(value||0)/1000000).toFixed(1)}M`;return `<div class="data-provenance connected"><strong>SUPABASE LIVE · RETURNS</strong><span>최근 ${data.periodDays}일 · 판매 주문과 반품 수량·취소 상태 기준</span><button class="btn" id="refreshReturnInsights">새로고침</button></div>${kpi([['반품률',`${Number(s.returnRate||0).toFixed(1)}%`,`${Number(s.returnedQty||0).toLocaleString()} / ${Number(s.orderedQty||0).toLocaleString()} pcs`],['취소율',`${Number(s.cancelRate||0).toFixed(1)}%`,`${Number(s.cancelledQty||0).toLocaleString()} pcs`],['반품·취소 손실',moneyM(Number(s.refundAmount||0)+Number(s.cancelAmount||0)),'수량 비례 추정'],['처리비용',moneyM(s.processingCost),'파일 입력값 합계']])}<div class="grid split"><section class="card panel"><div class="panel-title"><div><h2>채널별 반품·취소</h2><span class="subtle">실제 주문·라인 집계</span></div>${tag('LIVE')}</div><table class="table"><thead><tr><th>채널</th><th>주문 수량</th><th>반품률</th><th>취소율</th><th>손실 영향</th></tr></thead><tbody>${channels.map(row=>`<tr><td><strong>${escapeHtml(row.label)}</strong></td><td>${Number(row.ordered_qty).toLocaleString()} pcs</td><td>${Number(row.return_rate).toFixed(1)}%</td><td>${Number(row.cancel_rate).toFixed(1)}%</td><td>${moneyM(row.loss_amount)}</td></tr>`).join('')}</tbody></table></section><section class="card panel"><h2>반품 사유 데이터 준비도</h2><div class="operational-empty compact"><strong>사유 코드 추가 연결 필요</strong><p>${escapeHtml(data.reasonCoverage?.message||'반품 사유를 연결해주세요.')}</p></div><div class="phase3-callout"><strong>현재는 수량·금액·채널·제품 위험을 실제 데이터로 계산합니다.</strong><button data-query="반품률과 취소율이 높은 채널과 제품을 우선순위로 정리해줘">AX 위험 분석</button></div></section></div><section class="card panel"><div class="panel-title"><div><h2>제품별 반품·취소 위험</h2><span class="subtle">반품률 + 취소율 순</span></div></div><table class="table"><thead><tr><th>제품</th><th>판매 수량</th><th>반품 수량</th><th>취소 수량</th><th>반품률</th><th>취소율</th></tr></thead><tbody>${products.slice(0,15).map((row,index)=>`<tr><td><div class="product-cell">${row.image_url?thumb(String(row.image_url).split('/').pop(),row.label):thumb(productImages[index%productImages.length],row.label)}<div><strong>${escapeHtml(row.label)}</strong><small>${escapeHtml(row.product_code||'')}</small></div></div></td><td>${Number(row.ordered_qty).toLocaleString()}</td><td>${Number(row.returned_qty).toLocaleString()}</td><td>${Number(row.cancelled_qty).toLocaleString()}</td><td>${Number(row.return_rate).toFixed(1)}%</td><td>${Number(row.cancel_rate).toFixed(1)}%</td></tr>`).join('')}</tbody></table></section>`}
