function reviewVocDashboard(){const data=state.reviewDbData?.hasData?state.reviewDbData:reviewSampleData;if(state.reviewDbLoading&&!state.reviewDbData)return '<div class="card panel operational-loading">저장된 리뷰 속성과 감정을 집계하고 있습니다.</div>';const sample=!state.reviewDbData?.hasData,s=data.summary||{},aspects=data.aspects||[],reviewProducts=data.products||[],channels=data.channels||[],evidence=data.evidence||[],actions=data.actions||[],topAspects=aspects.filter(row=>row.aspect_code!=='overall').slice(0,5),maxAspect=Math.max(...topAspects.map(row=>Number(row.negative||0)),1);return `${state.reviewDbError?`<div class="data-provenance stale"><strong>리뷰 데이터 조회 실패</strong><span>${escapeHtml(state.reviewDbError)} · 샘플 화면으로 표시합니다.</span></div>`:`<div class="data-provenance ${sample?'sample':'connected'}"><strong>${sample?'REVIEW DEMO DATA':'SUPABASE LIVE · REVIEW SIGNALS'}</strong><span>최근 ${data.periodDays||90}일 · 원문은 보관하고 속성 분류 결과는 업로드 시 한 번 계산합니다.</span><button class="btn" id="refreshReviewInsights">새로고침</button></div>`}${kpi([['리뷰 수',`${Number(s.reviews||0).toLocaleString()}건`,sample?'샘플 12개 상품':'실제 업로드 기준'],['평균 평점',`${Number(s.averageRating||0).toFixed(1)} / 5`,`부정 ${Number(s.negativePct||0).toFixed(1)}%`],['응답 필요',`${Number(s.responseNeeded||0).toLocaleString()}건`,'부정 리뷰 중 미답변'],['반품 위험 신호',`${Number(s.returnRisk||0).toLocaleString()}건`,'핏·품질·소재·색상 연계']])}<div class="grid review-overview"><section class="card panel"><div class="panel-title"><div><h2>리뷰 속성별 정량 신호</h2><span class="subtle">한 리뷰에서 여러 속성을 동시에 인식</span></div>${tag('정량화')}</div><div class="review-aspects">${topAspects.map(row=>`<div class="review-aspect"><div><strong>${escapeHtml(row.label)}</strong><span>${escapeHtml(row.team||'담당 확인')}</span></div><div class="review-sentiment-track"><i style="width:${Math.max(4,Number(row.positive||0)/Math.max(1,Number(row.total||0))*100)}%"></i><b style="width:${Math.max(2,Number(row.negative||0)/Math.max(1,Number(row.total||0))*100)}%"></b></div><em>긍정 ${Number(row.positive||0)} · 부정 ${Number(row.negative||0)}</em></div>`).join('')}</div></section><section class="card panel review-channel-card"><h2>플랫폼별 리뷰 건강도</h2>${channels.slice(0,6).map(row=>`<div class="review-channel-row"><strong>${escapeHtml(row.platform)}</strong><span>★ ${Number(row.average_rating||0).toFixed(1)}</span><i><b style="width:${Math.min(100,Number(row.negative_pct||0)*4)}%"></b></i><em>부정 ${Number(row.negative_pct||0).toFixed(1)}%</em></div>`).join('')}</section></div><section class="card panel review-product-panel"><div class="panel-title"><div><h2>상품 × 리뷰 주제 위험</h2><span class="subtle">부정 비율이 높은 상품부터 · 상품 이미지를 함께 확인</span></div><button data-query="최근 리뷰에서 부정 신호가 커진 상품과 원인을 보여줘" class="btn">AX로 원인 분석</button></div><div class="review-product-grid">${reviewProducts.slice(0,8).map((row,index)=>`<article class="review-product"><div class="review-product-head">${reviewImage(row.image_url,index)}<div><strong>${escapeHtml(row.product_name||row.product_code)}</strong><small>${escapeHtml(row.product_code)}</small><span>★ ${Number(row.average_rating||0).toFixed(1)} · ${Number(row.reviews||0)}건</span></div></div><div class="review-risk"><span>부정 리뷰</span><strong>${Number(row.negative_pct||0).toFixed(1)}%</strong></div><div class="review-topic-chips">${topAspects.map(aspect=>{const count=Number(row.topics?.[aspect.aspect_code]||0),level=count/maxAspect;return `<span class="${level>.5?'high':level>.15?'mid':''}">${escapeHtml(aspect.label)} ${count}</span>`}).join('')}</div></article>`).join('')}</div></section><div class="grid review-bottom"><section class="card panel"><div class="panel-title"><div><h2>근거 리뷰</h2><span class="subtle">수치 뒤의 실제 문장 · 직접 식별정보 제외</span></div>${tag('EVIDENCE')}</div><div class="review-evidence-list">${evidence.slice(0,6).map(row=>`<article><header><strong>${escapeHtml(row.product_name||row.product_code)}</strong><span>${escapeHtml(row.platform)} · ★ ${Number(row.rating).toFixed(0)}</span></header><p>${escapeHtml(row.review_text)}</p><footer>${(row.topics||[]).map(topic=>`<span>${escapeHtml(topic)}</span>`).join('')}${row.return_risk?'<b>반품 위험</b>':''}${row.response_status==='pending'?'<em>응답 필요</em>':''}</footer></article>`).join('')}</div></section><section class="card panel"><h2>팀별 다음 행동</h2><div class="review-action-list">${actions.map((row,index)=>`<button data-query="${escapeHtml(row.title)}의 리뷰 근거와 실행 우선순위를 정리해줘"><span>${index+1}</span><div><strong>${escapeHtml(row.title)}</strong><small>${escapeHtml(row.team)} · ${escapeHtml(row.detail)}</small></div><i>AX로 보기 →</i></button>`).join('')}</div><div class="review-link-note"><strong>반품·취소와 함께 보기</strong><p>리뷰는 고객의 언어를 분석하고, 반품·취소 메뉴는 실제 손실 수량과 금액을 추적합니다.</p><button class="btn" data-page="returns">반품·취소 데이터 열기</button></div></section></div>`}
function customerTabs(){return `<nav class="customer-tabs customer-journey-nav" aria-label="고객 인사이트 섹션"><button class="active" data-customer-anchor="customer-status"><b>01</b> 고객 현황</button><button data-customer-anchor="customer-why"><b>02</b> 변화 원인</button><button data-customer-anchor="customer-voc"><b>03</b> 리뷰·VOC</button><button data-customer-anchor="customer-actions"><b>04</b> 실행 제안</button></nav>`}
function customerInsightBridge(){const customer=state.customerDbData?.hasData?state.customerDbData:null,review=state.reviewDbData?.hasData?state.reviewDbData:reviewSampleData,summary=customer?.summary||{},reviewSummary=review?.summary||{},topAspect=(review?.aspects||[]).filter(row=>row.aspect_code!=='overall').sort((a,b)=>Number(b.negative||0)-Number(a.negative||0))[0],topProduct=(review?.products||[]).sort((a,b)=>Number(b.negative_pct||0)-Number(a.negative_pct||0))[0],repeat=customer?`${Number(summary.repeatCustomerPct||0).toFixed(1)}%`:'53.7%';return `<section id="customer-why" class="customer-story-section customer-bridge"><div class="customer-section-head"><div><span>02 · WHY</span><h2>고객 변화의 원인을 좁혀봅니다</h2><p>고객 행동과 VOC를 같은 결론으로 단정하지 않고, 함께 확인할 우선순위를 제시합니다.</p></div><button class="btn" data-query="고객 현황 변화와 리뷰 VOC를 연결해 가장 먼저 확인할 원인을 정리해줘">AX 교차 분석</button></div><div class="customer-signal-grid"><article><span>고객 행동</span><strong>재구매 고객 ${repeat}</strong><p>상품·채널별 재구매 차이가 큰 구간부터 확인합니다.</p></article><article><span>주요 VOC</span><strong>${escapeHtml(topAspect?.label||'사이즈·핏')} 부정 ${Number(topAspect?.negative||0).toLocaleString()}건</strong><p>반품과 재구매 저하가 동시에 나타나는 상품을 우선 점검합니다.</p></article><article><span>우선 상품</span><strong>${escapeHtml(topProduct?.product_name||topProduct?.product_code||'리뷰 위험 상품')}</strong><p>부정 리뷰 ${Number(topProduct?.negative_pct||0).toFixed(1)}% · 원문 근거를 검토합니다.</p></article><article class="customer-signal-action"><span>이번 주 권장 흐름</span><strong>원인 확인 → 담당 배정 → 효과 측정</strong><p>응답 필요 ${Number(reviewSummary.responseNeeded||0).toLocaleString()}건과 반품 위험 ${Number(reviewSummary.returnRisk||0).toLocaleString()}건을 실행 큐로 연결합니다.</p></article></div></section>`}
function customersDashboard(){const overview=state.backendMode==='connected'?customerLiveDashboard():customersDashboardSample()+customerLtvBlock();return `<section class="customer-insight-hero"><div><span>CUSTOMER SIGNALS</span><h2>고객의 변화에서 시작해, 목소리와 실행까지 연결합니다</h2><p>누가 어떻게 변했는지 먼저 확인하고 리뷰·VOC로 원인을 좁힌 뒤 담당 팀의 다음 행동을 결정합니다.</p></div><div class="customer-hero-flow"><span class="active">현황</span><i></i><span>원인</span><i></i><span>VOC</span><i></i><span>액션</span></div></section>${customerTabs()}<section id="customer-status" class="customer-story-section"><div class="customer-section-head"><div><span>01 · WHAT</span><h2>고객 현황</h2><p>고객 규모, 재구매 행동, 지역과 세그먼트의 변화를 먼저 확인합니다.</p></div></div>${overview}</section>${customerInsightBridge()}<section id="customer-voc" class="customer-story-section"><div class="customer-section-head"><div><span>03 · VOICE</span><h2>리뷰·VOC</h2><p>정량 지표 뒤에 있는 고객의 표현을 상품·속성·채널 단위로 확인합니다.</p></div></div>${reviewVocDashboard()}</section><section id="customer-actions" class="customer-closing-cta"><div><span>04 · ACTION</span><strong>고객 신호를 오늘의 실행으로 전환하세요</strong><p>VOC 조치 이후 재구매율·반품률·평점을 같은 기준으로 다시 측정합니다.</p></div><button data-query="고객 현황과 VOC를 바탕으로 오늘 실행할 일을 팀별로 정리해줘">팀별 실행안 만들기</button></section>`}
