function inventoryRisk(row){const cover=Number(row.inventory_cover_days);if(!Number.isFinite(cover)||cover<=0)return {label:'판매속도 확인',tone:'warning',className:'',action:'판매 연결 확인'};if(cover<7)return {label:'품절 위험',tone:'danger',className:'risk',action:'이동·재주문'};if(cover>45)return {label:'과잉',tone:'warning',className:'over',action:'채널 이동·소진'};if(cover<14)return {label:'주의',tone:'warning',className:'risk',action:'재고 모니터링'};return {label:'정상',tone:'',className:'',action:'유지'}}
function inventoryLiveDiagnosis(){const data=state.inventoryDbData,productRows=(data?.products||[]).map(row=>({...row,available_qty:Number(row.available_qty||0),inventory_cover_days:row.inventory_cover_days==null?null:Number(row.inventory_cover_days),sell_through_rate:row.sell_through_rate==null?null:Number(row.sell_through_rate)})),locationRows=(data?.locations||[]).map(row=>({...row,available_qty:Number(row.available_qty||0),inventory_cover_days:row.inventory_cover_days==null?null:Number(row.inventory_cover_days)})),total=productRows.reduce((sum,row)=>sum+row.available_qty,0),low=productRows.filter(row=>row.inventory_cover_days!=null&&row.inventory_cover_days<7),watch=productRows.filter(row=>row.inventory_cover_days!=null&&row.inventory_cover_days>=7&&row.inventory_cover_days<14),over=productRows.filter(row=>row.inventory_cover_days!=null&&row.inventory_cover_days>45),maxAvailable=Math.max(...productRows.map(row=>row.available_qty),1),maxLocation=Math.max(...locationRows.map(row=>row.available_qty),1),sorted=[...productRows].sort((a,b)=>{const ar=inventoryRisk(a),br=inventoryRisk(b),score=r=>r.tone==='danger'?0:r.label==='주의'?1:r.label==='과잉'?2:3;return score(ar)-score(br)||a.inventory_cover_days-b.inventory_cover_days}),fresh=data?.lastSnapshotAt?new Date(data.lastSnapshotAt).toLocaleString('ko-KR'):'스냅샷 없음',source=data?.sourceStatus;return `<div class="data-provenance ${data?.dataMode==='stale'?'stale':'connected'}"><strong>${data?.dataMode==='stale'?'WMS 연결 확인':'SUPABASE LIVE · WMS'}</strong><span>최신 재고 스냅샷 ${escapeHtml(fresh)} · 상품 ${productRows.length}개 · 위치 ${locationRows.length}곳</span>${source?.last_sync_error?`<em>${escapeHtml(source.last_sync_error)}</em>`:''}<button class="btn" id="refreshInventory">새로고침</button></div>${kpi([['총 가용재고',`${Math.round(total).toLocaleString()} pcs`,`${locationRows.length}개 위치`],['7일 내 품절 위험',`${low.length} SKU`,watch.length?`주의 ${watch.length} SKU`:'추가 주의 없음'],['과잉 재고',`${over.length} SKU`,'커버 45일 초과'],['마지막 WMS 반영',data?.lastSuccessfulSyncAt?new Date(data.lastSuccessfulSyncAt).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'}):'미확인',data?.dataMode==='stale'?'연결 지연':'정상 연결']])}<div class="inventory-tabs">${[['diagnosis','진단'],['actions','이동·재주문'],['inbound','입고·배송']].map(([id,label])=>`<button data-inventory-tab="${id}" class="${state.inventoryTab===id?'active':''}">${label}</button>`).join('')}</div><div class="grid inventory-viz-grid"><div class="card panel quadrant-panel"><div class="panel-title"><div><h2>실제 판매속도 × 재고커버</h2><span class="subtle">최신 가용재고와 최근 14일 판매속도 · 버블 크기 = 가용재고</span></div>${semanticLegend([['정상','var(--operations)'],['과잉','var(--target)'],['품절 위험','var(--risk)']])}</div><div class="quadrant"><div class="quadrant-y">재고 커버일수 ↑</div><div><div class="quadrant-plot"><span class="quadrant-label q1">저판매 · 충분재고</span><span class="quadrant-label q2">고판매 · 충분재고</span><span class="quadrant-label q3">저판매 · 부족재고</span><span class="quadrant-label q4">고판매 · 부족재고</span>${productRows.slice(0,12).map((row,index)=>{const risk=inventoryRisk(row),velocity=row.inventory_cover_days?row.available_qty/row.inventory_cover_days:0,x=Math.max(12,Math.min(88,20+velocity*3)),y=Math.max(12,Math.min(88,(row.inventory_cover_days||18)/60*78)),size=Math.max(38,Math.min(66,38+row.available_qty/maxAvailable*28)),label=String(row.label||`SKU ${index+1}`).split(' ')[0].slice(0,11);return `<div class="sku-bubble ${risk.className}" style="--x:${x}%;--y:${y}%;--size:${size}px" title="${escapeHtml(row.label)} · ${row.available_qty.toLocaleString()}pcs · 커버 ${row.inventory_cover_days==null?'미확인':`${row.inventory_cover_days}일`}">${escapeHtml(label)}</div>`}).join('')}</div><div class="quadrant-x">일평균 판매속도 →</div></div></div></div><div class="card panel"><div class="panel-title"><div><h2>위치별 실제 가용재고</h2><span class="subtle">최신 WMS 스냅샷 · 커버일수 병기</span></div>${tag(data?.dataMode==='stale'?'STALE':'LIVE',data?.dataMode==='stale'?'warning':'')}</div>${locationRows.length?bars(locationRows.slice(0,10).map(row=>[escapeHtml(row.label),`${Math.round(row.available_qty).toLocaleString()} pcs · ${row.inventory_cover_days==null?'판매속도 미확인':`커버 ${row.inventory_cover_days}일`}`,Math.max(5,row.available_qty/maxLocation*100),row.inventory_cover_days!=null&&row.inventory_cover_days<7?'warning':''])):'<div class="operational-empty compact"><strong>위치별 재고가 없습니다.</strong><p>위치 코드가 포함된 WMS 파일을 적재해주세요.</p></div>'}<div class="inventory-summary"><div><span>품절 위험</span><strong>${low.length} SKU</strong></div><div><span>주의</span><strong>${watch.length} SKU</strong></div><div><span>정상·확인 중</span><strong>${Math.max(0,productRows.length-low.length-watch.length-over.length)} SKU</strong></div><div><span>과잉</span><strong>${over.length} SKU</strong></div></div></div></div><div class="card panel inventory-table-panel"><div class="panel-title"><div><h2>상품별 실제 재고 진단</h2><span class="subtle">최신 재고·최근 14일 판매속도 기준</span></div><span class="subtle">${escapeHtml(fresh)}</span></div><table class="table"><thead><tr><th>제품</th><th>가용재고</th><th>일 판매속도</th><th>커버일수</th><th>판매율</th><th>상태</th><th>권장 행동</th></tr></thead><tbody>${sorted.map((row,index)=>{const risk=inventoryRisk(row),daily=row.inventory_cover_days?row.available_qty/row.inventory_cover_days:null,file=row.image_url?String(row.image_url).split('/').pop():productImages[index%productImages.length];return `<tr><td><div class="product-cell">${thumb(file,row.label)}<div><strong>${escapeHtml(row.label)}</strong><small>운영 DB</small></div></div></td><td><strong>${Math.round(row.available_qty).toLocaleString()} pcs</strong></td><td>${daily==null?'—':`${daily.toFixed(1)} pcs`}</td><td><span class="cover ${risk.tone==='danger'?'danger':risk.tone==='warning'?'warning':''}">${row.inventory_cover_days==null?'—':`${row.inventory_cover_days.toFixed(1)}일`}</span></td><td>${row.sell_through_rate==null?'—':`${row.sell_through_rate.toFixed(1)}%`}</td><td>${tag(risk.label,risk.tone)}</td><td><button class="btn" data-query="${axEscape(row.label)}의 재고 상태와 ${risk.action} 수량을 분석해줘">${risk.action}</button></td></tr>`}).join('')||'<tr><td colspan="7">적재된 재고 스냅샷이 없습니다.</td></tr>'}</tbody></table></div>`}
function inventoryTabbar(){return `<div class="inventory-tabs">${[['diagnosis','진단'],['actions','이동·재주문'],['inbound','입고·배송']].map(([id,label])=>`<button data-inventory-tab="${id}" class="${state.inventoryTab===id?'active':''}">${label}</button>`).join('')}</div>`}
function workflowStatus(status){const labels={recommended:'승인 대기',approved:'승인 완료',integrity_error:'연결 오류',in_transit:'이동 중',received:'입고 완료',delayed:'지연',proposed:'승인 대기',held:'보류',planning:'생산 계획',materials:'원부자재',cutting:'재단',sewing:'봉제',inspection:'검품',completed:'생산 완료',executed:'실행 완료'},tone=['delayed','held','integrity_error'].includes(status)?'danger':['recommended','proposed'].includes(status)?'warning':'';return tag(labels[status]||status||'확인',tone)}
function inventoryWorkflowShell(content){const data=state.inventoryWorkflowData,summary=data?.summary||{},canRefresh=['owner','admin'].includes(state.currentUser?.backendRole)||['대표','전체 관리자'].includes(state.currentUser?.role);return `<div class="data-provenance connected"><strong>SUPABASE WORKFLOW</strong><span>이동 승인·재주문 결정·배송 상태가 회사별 실행 이력으로 저장됩니다.</span><div class="workflow-toolbar">${canRefresh?`<button class="btn" id="refreshInventoryForecast" ${state.inventoryForecastRefreshing?'disabled':''}>${state.inventoryForecastRefreshing?'28일 예측 계산 중…':'28일 예측 갱신'}</button>`:''}<button class="btn" id="refreshInventoryWorkflow">새로고침</button></div></div>${kpi([['이동 승인 대기',`${Number(summary.transferProposals||0)}건`,'재고 불균형 자동 계산'],['승인된 이동',`${Number(summary.approvedTransfers||0)}건`,'배송 큐 자동 생성'],['재주문 검토',`${Number(summary.reorderProposals||0)}건`,summary.forecastHorizon?`${summary.forecastHorizon}일 저장 예측`:'저장된 수요예측'],['배송 위험',`${Number(summary.shipmentRisks||0)}건`,'지연 상태']])}${inventoryTabbar()}${content}`}
function inventoryLiveActions(){const data=state.inventoryWorkflowData,transfers=data?.transfers||[],reorders=data?.reorders||[];return inventoryWorkflowShell(`<div class="grid split inventory-actions operational-workflow"><section class="card panel"><div class="panel-title"><div><h2>매장·창고 간 이동 제안</h2><span class="subtle">동일 SKU의 최신 위치별 가용재고 격차로 계산</span></div>${tag(`${transfers.length}건`)}</div>${transfers.length?`<div class="preview-scroll"><table class="table"><thead><tr><th>상품</th><th>출발 → 도착</th><th>권장 수량</th><th>근거</th><th>상태·실행</th></tr></thead><tbody>${transfers.map(row=>{const qty=Math.round(Number(row.approved_qty||row.recommended_qty||0)),busy=state.inventoryActionBusy.includes(row.id||row.proposal_key||'__'),fromAvailable=Number(row.reason?.from_available),toAvailable=Number(row.reason?.to_available),hasInventoryEvidence=Number.isFinite(fromAvailable)&&Number.isFinite(toAvailable);return `<tr><td><strong>${escapeHtml(row.sku?.product_code||row.sku?.sku_code)}</strong><small>${escapeHtml(row.sku?.product_name||'')}</small></td><td>${escapeHtml(row.from_location?.location_name)} → ${escapeHtml(row.to_location?.location_name)}</td><td><strong>${qty.toLocaleString()} pcs</strong></td><td>${hasInventoryEvidence?`출발 ${fromAvailable.toLocaleString()} · 도착 ${toAvailable.toLocaleString()}`:row.status==='approved'?'재고 불균형 검증 완료':'승인된 운영안'}</td><td>${workflowStatus(row.status)}${row.status==='recommended'?`<button class="btn primary inventory-row-action" data-inventory-action="approve_transfer" data-transfer-id="${row.id||''}" data-proposal-key="${escapeHtml(row.proposal_key||'')}" data-sku-id="${row.sku_id}" data-from-location="${row.from_location_id}" data-to-location="${row.to_location_id}" data-quantity="${qty}" data-from-available="${fromAvailable}" data-to-available="${toAvailable}" ${busy?'disabled':''}>${busy?'저장 중…':'이동 승인'}</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="operational-empty compact"><strong>현재 이동 제안이 없습니다.</strong><p>위치별 재고 격차가 기준 이상이면 자동으로 제안됩니다.</p></div>'}</section><section class="card panel"><div class="panel-title"><div><h2>재주문 판단</h2><span class="subtle">28일 수요 + 생산 리드타임 14일 + 안전재고 기준</span></div>${tag(`${reorders.length}건`)}</div>${reorders.length?`<div class="preview-scroll"><table class="table"><thead><tr><th>제품</th><th>예측 기간·수요</th><th>현재 재고</th><th>권장 수량</th><th>신뢰도</th><th>결정</th></tr></thead><tbody>${reorders.map(row=>{const qty=Math.round(Number(row.recommended_reorder_qty||0)),busy=state.inventoryActionBusy.includes(row.product_code||'__');return `<tr><td><strong>${escapeHtml(row.product_code)}</strong><small>${escapeHtml(row.product_name||'')}</small></td><td><strong>${Number(row.horizon_days||28)}일 · ${Math.round(Number(row.forecast_quantity||0)).toLocaleString()} pcs</strong><small>예상 매출 ₩${Math.round(Number(row.forecast_net_sales||0)/1000000).toLocaleString()}M</small></td><td>${Math.round(Number(row.available_qty||0)).toLocaleString()} pcs</td><td><strong>${qty.toLocaleString()} pcs</strong><small>리드타임 ${Number(row.planning_lead_time_days||14)}일 포함</small></td><td>${Math.round(Number(row.confidence||0)*100)}%</td><td>${workflowStatus(row.status)}${row.status!=='approved'?`<button class="btn primary inventory-row-action" data-inventory-action="approve_reorder" data-product-code="${escapeHtml(row.product_code)}" data-product-name="${escapeHtml(row.product_name||'')}" data-quantity="${qty}" data-forecast-quantity="${Number(row.forecast_quantity||0)}" data-forecast-sales="${Number(row.forecast_net_sales||0)}" data-available-quantity="${Number(row.available_qty||0)}" data-confidence="${Number(row.confidence||0)}" data-horizon-days="${Number(row.horizon_days||28)}" ${busy?'disabled':''}>${busy?'저장 중…':'재주문 승인'}</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="operational-empty compact"><strong>현재 재주문 대상이 없습니다.</strong><p>28일 예측을 갱신한 뒤 생산 리드타임까지 포함한 부족 수량이 표시됩니다.</p></div>'}</section></div>`)}
function inventoryLiveInbound(){const data=state.inventoryWorkflowData,shipments=data?.shipments||[];return inventoryWorkflowShell(`<section class="card panel inbound-board operational-workflow"><div class="panel-title"><div><h2>입고·배송 실행 보드</h2><span class="subtle">이동 승인 시 배송 건이 자동 생성되고 상태 변경 이력이 감사 로그에 남습니다</span></div>${tag(`${shipments.length}건`)}</div>${shipments.length?`<div class="preview-scroll"><table class="table"><thead><tr><th>운송</th><th>상품</th><th>출발 → 도착</th><th>수량</th><th>최근 처리</th><th>상태·다음 실행</th></tr></thead><tbody>${shipments.map(row=>{const next=row.next_status,busy=state.inventoryActionBusy.includes(row.id||'__'),nextLabel=next==='in_transit'?'출고 처리':next==='received'?'입고 완료':'';return `<tr><td><strong>${escapeHtml(row.reference_no||String(row.id).slice(0,8))}</strong><small>${escapeHtml(row.movement_type)}</small></td><td><strong>${escapeHtml(row.sku?.product_code||row.sku?.sku_code)}</strong><small>${escapeHtml(row.sku?.product_name||'')}</small></td><td>${escapeHtml(row.from_location?.location_name||'외부')} → ${escapeHtml(row.to_location?.location_name||'미정')}</td><td>${Math.round(Number(row.quantity||0)).toLocaleString()} pcs</td><td>${new Date(row.occurred_at).toLocaleString('ko-KR')}</td><td>${workflowStatus(row.status)}${next?`<button class="btn primary inventory-row-action" data-inventory-action="update_shipment" data-movement-id="${row.id}" data-current-status="${escapeHtml(row.status||'')}" data-next-status="${next}" ${busy?'disabled':''}>${busy?'저장 중…':nextLabel}</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="operational-empty"><strong>아직 실행 중인 입고·배송 건이 없습니다.</strong><p>‘이동·재주문’에서 재고 이동을 승인하면 이 보드에 배송 건이 생성됩니다.</p></div>'}</section>`)}
inventoryOperationsDashboard=function(){if(state.backendMode!=='connected')return inventoryOperationsDashboardSample();if(state.inventoryTab!=='diagnosis'){if(state.inventoryWorkflowLoading&&!state.inventoryWorkflowData)return `${inventoryTabbar()}<div class="card panel operational-loading">실행 이력을 불러오는 중입니다.</div>`;if(state.inventoryWorkflowError&&!state.inventoryWorkflowData)return `${inventoryTabbar()}<div class="data-provenance stale"><strong>실행 데이터 조회 실패</strong><span>${escapeHtml(state.inventoryWorkflowError)}</span><button class="btn" id="refreshInventoryWorkflow">다시 시도</button></div>`;return state.inventoryTab==='actions'?inventoryLiveActions():inventoryLiveInbound()}if(state.inventoryDbLoading&&!state.inventoryDbData)return '<div class="card panel"><h2>실제 WMS 재고를 불러오는 중입니다.</h2><p class="subtle">회사·위치 권한 범위와 최신 스냅샷을 확인하고 있습니다.</p></div>';if(state.inventoryDbError&&!state.inventoryDbData)return `<div class="data-provenance stale"><strong>재고 조회 실패</strong><span>${escapeHtml(state.inventoryDbError)}</span><button class="btn" id="refreshInventory">다시 시도</button></div>${inventoryOperationsDashboardSample()}`;if(!state.inventoryDbData?.hasData){const diagnostic=state.inventoryDbData?.diagnostics||{},job=diagnostic.latestInventoryJobId?`기준 적재 ${String(diagnostic.latestInventoryJobId).slice(0,8)}`:'최근 재고 적재 미발견',mode=diagnostic.readMode==='latest_snapshot'?'최신 재고 기준일':'회사 전체 기준';return `<div class="data-provenance sample"><strong>WMS 데이터 없음</strong><span>${mode} · ${job} · 스냅샷 ${Number(diagnostic.snapshotRows||0).toLocaleString()}행 · SKU ${Number(diagnostic.skuRows||0).toLocaleString()}행 · 위치 ${Number(diagnostic.locationRows||0).toLocaleString()}행 · 권한 적용 후 상품 ${Number(diagnostic.scopedProductRows||0).toLocaleString()}개</span><button class="btn" id="refreshInventory">다시 확인</button><button class="btn" data-page="connections">재고 파일 연결</button></div>${inventoryOperationsDashboardSample()}`};return inventoryLiveDiagnosis()};
const productionDashboardSample=productionDashboard;
const productionStageMeta={approved:['승인됨',0,'planning','생산 계획 시작'],planning:['생산 계획',10,'materials','원부자재 착수'],materials:['원부자재',25,'cutting','재단 시작'],cutting:['재단',42,'sewing','봉제 시작'],sewing:['봉제',68,'inspection','검품 시작'],inspection:['검품',88,'completed','생산 완료'],completed:['완료',100,null,null],held:['보류',0,'planning','계획 재개']};
function productionLiveDashboard(){const data=state.productionWorkflowData;if(state.productionWorkflowLoading&&!data)return '<div class="card panel operational-loading">승인된 재주문과 생산 실행 상태를 불러오는 중입니다.</div>';if(state.productionWorkflowError&&!data)return `<div class="data-provenance stale"><strong>생산 실행 큐 조회 실패</strong><span>${escapeHtml(state.productionWorkflowError)}</span><button class="btn" id="refreshProductionWorkflow">다시 시도</button></div>`;const orders=data?.orders||[],summary=data?.summary||{},money=value=>`₩${Math.round(Number(value||0)/1000000).toLocaleString()}M`;return `<div class="data-provenance connected"><strong>FORECAST → REORDER → PRODUCTION</strong><span>재고팀에서 승인한 재주문이 생산 실행 큐로 자동 전달됩니다.</span><button class="btn" id="refreshProductionWorkflow">새로고침</button></div>${kpi([['생산 실행 큐',`${Number(summary.total||0)}건`,`${Number(summary.totalQuantity||0).toLocaleString()} pcs`],['진행 중',`${Number(summary.inProgress||0)}건`,'계획·원부자재·재단·봉제·검품'],['완료',`${Number(summary.completed||0)}건`,'실행 이력 저장'],['보호 예상 매출',money(summary.protectedSales),'28일 수요예측 기준']])}<section class="card panel production-orders operational-workflow"><div class="panel-title"><div><h2>재주문 승인 기반 생산 실행 큐</h2><span class="subtle">예측 근거 · 승인 수량 · 공정 상태 · 다음 실행</span></div>${tag(`${orders.length} PO`)}</div>${orders.length?`<div class="preview-scroll"><table class="table production-table"><thead><tr><th>생산오더·제품</th><th>승인 수량</th><th>28일 수요·재고</th><th>현재 공정</th><th>진척</th><th>다음 실행</th></tr></thead><tbody>${orders.map(row=>{const meta=productionStageMeta[row.production_status]||productionStageMeta.approved,busy=state.productionActionBusy===row.id;return `<tr><td><div class="product-cell">${row.image_url?thumb(String(row.image_url).split('/').pop(),row.product_name):''}<div><strong>${escapeHtml(row.production_order_no)} · ${escapeHtml(row.product_name||row.product_code)}</strong><small>${escapeHtml(row.product_code)} · ${row.due_date?`입고 목표 ${escapeHtml(row.due_date)}`:'입고일 미정'}</small></div></div></td><td><strong>${Number(row.quantity||0).toLocaleString()} pcs</strong><small>${Math.round(Number(row.confidence||0)*100)}% 신뢰도</small></td><td><strong>${Number(row.forecast_quantity||0).toLocaleString()} / ${Number(row.available_qty||0).toLocaleString()} pcs</strong><small>보호 매출 ${money(row.forecast_net_sales)}</small></td><td>${workflowStatus(row.production_status)}<small>${escapeHtml(row.factory||'공장 미배정')}</small></td><td><div class="production-progress"><i><b style="width:${Number(row.progress??meta[1])}%"></b></i><span>${Number(row.progress??meta[1])}%</span></div></td><td>${meta[2]?`<button class="btn primary inventory-row-action" data-production-action="${meta[2]}" data-production-id="${row.id}" ${busy?'disabled':''}>${busy?'저장 중…':meta[3]}</button>`:'완료'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="operational-empty"><strong>승인된 재주문이 아직 없습니다.</strong><p>재고 운영의 ‘이동·재주문’에서 28일 예측을 갱신하고 재주문을 승인하면 자동으로 표시됩니다.</p><button class="btn" data-page="inventory">재고 운영으로 이동</button></div>'}</section><div class="grid split"><section class="card panel compact-panel"><h2>공정 운영 원칙</h2><div class="ai-list"><div><strong>재주문 승인 전에는 생산 큐가 생성되지 않습니다.</strong><span>예측 근거와 승인 주체를 함께 보존합니다.</span></div><div><strong>공정 전환은 담당 권한이 있는 사용자만 실행합니다.</strong><span>모든 변경은 회사별 감사 로그에 저장됩니다.</span></div></div></section><section class="card panel compact-panel"><h2>VIIM AX 추천 질문</h2><div class="ai-list"><button data-query="승인된 생산오더 중 납기와 수요를 기준으로 우선순위를 정해줘">어떤 생산오더를 먼저 진행해야 하나요?</button><button data-query="재주문 수량과 28일 예측의 차이를 제품별로 설명해줘">승인 수량의 근거를 비교해줘</button></div></section></div>`}
function productionLiveDashboardWithIntegrity(){const data=state.productionWorkflowData,integrity=data?.integrity||{},canRepair=['owner','admin'].includes(state.currentUser?.backendRole)||['대표','전체 관리자'].includes(state.currentUser?.role),busy=state.productionActionBusy==='integrity-repair',banner=Number(integrity.issueCount||0)>0?`<div class="data-provenance stale"><strong>재주문 실행 연결 오류 ${Number(integrity.issueCount)}건</strong><span>승인 기록은 있지만 생산 실행 데이터가 없어 복구가 필요합니다.</span>${canRepair?`<button class="btn primary" id="repairProductionIntegrity" ${busy?'disabled':''}>${busy?'복구 중…':'생산 큐로 복구'}</button>`:''}</div>`:'';return banner+productionLiveDashboard()}
