function refreshDashboardBody(options={}){const expectedPage=options.expectedPage||state.page,scroll=options.scroll||'preserve';if(!state.authenticated||state.page!==expectedPage)return;dashboardRefreshRequest={expectedPage,scroll};if(dashboardRefreshFrame)return;dashboardRefreshFrame=requestAnimationFrame(()=>{dashboardRefreshFrame=0;const request=dashboardRefreshRequest;dashboardRefreshRequest=null;if(!request||state.page!==request.expectedPage)return;const started=performance.now(),dashboard=document.querySelector('.dashboard-body');if(!dashboard){render();return}const scrollTop=window.scrollY;imageCursor=0;dashboard.innerHTML=renderPage();try{bindPage();document.body.dataset.axBound='true'}catch(error){document.body.dataset.axBindError=error.message;console.error('[page bind]',error)}if(state.ai)refreshAxPanel({preserveDraft:true});dashboard.classList.remove('page-is-switching');recordPerformance('render',`refresh:${request.expectedPage}`,started);requestAnimationFrame(()=>window.scrollTo({top:request.scroll==='top'?0:scrollTop,behavior:'auto'}))})}
function queueCurrentPageData(){if(!state.authenticated||state.backendMode!=='connected')return;if(state.page==='action'&&!state.todayActionsData&&!state.todayActionsLoading)queueMicrotask(()=>loadTodayActions());if(state.page==='permissions'){if(!state.permissionUsers&&!state.permissionBusy)queueMicrotask(()=>loadPermissionUsers());if(!state.auditEvents&&!state.auditEventsLoading)queueMicrotask(()=>loadAuditEvents());if(!state.betaReadiness&&!state.betaReadinessLoading)queueMicrotask(()=>loadBetaReadiness())}if(state.page==='hub'&&!state.dbOverview&&!state.dbOverviewLoading)queueMicrotask(()=>loadDbOverview());if(state.page==='customers'&&!state.customerDbData&&!state.customerDbLoading)queueMicrotask(()=>loadCustomerInsights());if(state.page==='customers'&&!state.reviewDbData&&!state.reviewDbLoading)queueMicrotask(()=>loadReviewInsights());if(state.page==='returns'&&!state.returnsDbData&&!state.returnsDbLoading)queueMicrotask(()=>loadReturnInsights());if(state.page==='connections'){if(!state.dataSources&&!state.dataSourcesLoading)queueMicrotask(()=>loadDataSources());if(!state.mappingTemplates&&!state.mappingTemplatesLoading)queueMicrotask(()=>loadMappingTemplates());if(!state.importHistory&&!state.importHistoryLoading)queueMicrotask(()=>loadImportHistory());if(!state.dataReconciliation&&!state.dataReconciliationLoading)queueMicrotask(()=>loadReconciliation())}if(['connections','profitability'].includes(state.page)&&!state.profitabilityDbData&&!state.profitabilityDbLoading)queueMicrotask(()=>loadProfitabilitySummary());if(state.page==='profitability'&&!state.discountIntelligence&&!state.discountLoading)queueMicrotask(()=>loadDiscountIntelligence());if(state.page==='inventory'){if(!state.inventoryDbData&&!state.inventoryDbLoading)queueMicrotask(()=>loadInventoryOverview());if(!state.inventoryWorkflowData&&!state.inventoryWorkflowLoading)queueMicrotask(()=>loadInventoryWorkflows())}if(state.page==='production'&&!state.productionWorkflowData&&!state.productionWorkflowLoading)queueMicrotask(()=>loadProductionWorkflows());if(state.page==='market'){if(!state.marketDbData&&!state.marketDbLoading)queueMicrotask(()=>loadMarketOverview());if(!state.productIntelligence&&!state.intelligenceLoading)queueMicrotask(()=>loadProductIntelligence())}if(['owner','admin'].includes(state.currentUser?.backendRole)&&!state.dataQuality&&!state.dataQualityLoading)queueMicrotask(()=>loadDataQuality())}
function navigateDashboardPage(nextPage){if(!nextPage)return;if(nextPage===state.page){window.scrollTo({top:0,behavior:'auto'});return}const started=performance.now(),token=++navigationRenderToken;state.page=nextPage;state.menu=false;state.aiResult=null;state.aiQuery='';state.axDynamic=null;state.axMode='idle';state.axEvidence=false;state.axApproval=false;state.axApproved=false;imageCursor=0;document.body.dataset.pageId=state.page;document.body.dataset.brandId=currentBrandWorkspace().id;const dashboard=document.querySelector('.dashboard-body'),head=document.querySelector('.page-head'),breadcrumbs=document.querySelector('.breadcrumbs');if(!dashboard||!head||!breadcrumbs){render();return}const[title,sub]=pageMeta[state.page],workspace=currentBrandWorkspace();document.querySelector('.sidebar')?.classList.remove('open');document.querySelectorAll('.nav [data-page]').forEach(button=>button.classList.toggle('active',button.dataset.page===state.page));breadcrumbs.textContent=`${organizationLabel()} / ${workspace.name} / ${title}`;head.innerHTML=`<div><span class="workspace-context">${escapeHtml(workspace.name)} 워크스페이스</span><h1>${title}</h1><p>${sub}</p></div>`;dashboard.classList.add('page-is-switching');queueCurrentPageData();requestAnimationFrame(()=>{if(token!==navigationRenderToken||state.page!==nextPage)return;dashboard.innerHTML=renderPage();try{bindPage();document.body.dataset.axBound='true'}catch(error){document.body.dataset.axBindError=error.message;console.error('[page bind]',error)}if(state.ai)refreshAxPanel({preserveDraft:true});dashboard.classList.remove('page-is-switching');recordPerformance('navigation',nextPage,started);requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'auto'}))})}
function render(){if(!state.authenticated){document.body.dataset.view='login';delete document.body.dataset.pageId;delete document.body.dataset.brandId;document.querySelector('#app').innerHTML=state.authLink?passwordSetupPage():loginPage();state.authLink?bindPasswordSetup():bindLogin();return}document.body.dataset.view='dashboard';const currentSidebar=document.querySelector('.sidebar-scroll');if(currentSidebar)state.sidebarScroll=currentSidebar.scrollTop;imageCursor=0;document.body.dataset.pageId=state.page;document.body.dataset.brandId=currentBrandWorkspace().id;document.querySelector('#app').innerHTML=shell();const nextSidebar=document.querySelector('.sidebar-scroll');if(nextSidebar)nextSidebar.scrollTop=state.sidebarScroll;try{bindPage();document.body.dataset.axBound='true'}catch(error){document.body.dataset.axBindError=error.message;console.error('[AX bind]',error)}if(state.page==='action'&&state.backendMode==='connected'&&!state.todayActionsData&&!state.todayActionsLoading)queueMicrotask(()=>loadTodayActions());if(['decisions','execution'].includes(state.page)&&state.backendMode==='connected'&&!state.decisionWorkflowData&&!state.decisionWorkflowLoading)queueMicrotask(()=>loadDecisionWorkflow());if(state.page==='permissions'&&state.backendMode==='connected'){if(!state.permissionUsers&&!state.permissionBusy)queueMicrotask(()=>loadPermissionUsers());if(!state.auditEvents&&!state.auditEventsLoading)queueMicrotask(()=>loadAuditEvents());if(!state.betaReadiness&&!state.betaReadinessLoading)queueMicrotask(()=>loadBetaReadiness())}if(state.page==='hub'&&state.backendMode==='connected'&&!state.dbOverview&&!state.dbOverviewLoading)queueMicrotask(()=>loadDbOverview());if(state.page==='customers'&&state.backendMode==='connected'&&!state.customerDbData&&!state.customerDbLoading)queueMicrotask(()=>loadCustomerInsights());if(state.page==='customers'&&state.backendMode==='connected'&&!state.reviewDbData&&!state.reviewDbLoading)queueMicrotask(()=>loadReviewInsights());if(state.page==='returns'&&state.backendMode==='connected'&&!state.returnsDbData&&!state.returnsDbLoading)queueMicrotask(()=>loadReturnInsights());if(state.page==='connections'&&state.backendMode==='connected'){if(!state.dataSources&&!state.dataSourcesLoading)queueMicrotask(()=>loadDataSources());if(!state.mappingTemplates&&!state.mappingTemplatesLoading)queueMicrotask(()=>loadMappingTemplates())}if(['connections','profitability'].includes(state.page)&&state.backendMode==='connected'&&!state.profitabilityDbData&&!state.profitabilityDbLoading)queueMicrotask(()=>loadProfitabilitySummary());if(state.page==='inventory'&&state.backendMode==='connected'){if(!state.inventoryDbData&&!state.inventoryDbLoading)queueMicrotask(()=>loadInventoryOverview());if(state.inventoryTab!=='diagnosis'&&!state.inventoryWorkflowData&&!state.inventoryWorkflowLoading)queueMicrotask(()=>loadInventoryWorkflows())}if(state.page==='production'&&state.backendMode==='connected'&&!state.productionWorkflowData&&!state.productionWorkflowLoading)queueMicrotask(()=>loadProductionWorkflows());if(state.page==='market'&&state.backendMode==='connected'){if(!state.marketDbData&&!state.marketDbLoading)queueMicrotask(()=>loadMarketOverview());if(!state.productIntelligence&&!state.intelligenceLoading)queueMicrotask(()=>loadProductIntelligence())}}
